                              <div className="flex min-w-0 flex-1 items-center gap-2">
                                <span className="shrink-0 rounded bg-[#FAF9F7] border border-[#E5E2DC] px-2 py-0.5 text-hb-xs font-semibold text-[#0E1A2B]">
