                      } else {
                        addBulkEquipmentRow(preset);
                      }
                    }}
                    className="rounded-lg border border-[#D7D2C8] bg-white px-3 py-1.5 text-hb-sm font-bold text-[#0E1A2B] hover:border-[#0E1A2B]"
