            {!isNotice && !isOther && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5 sm:gap-4">
                <div>
                  <label htmlFor="uf-cat" className="hb-label">
                    제품 종류
                  </label>
                  <select
                    id="uf-cat"
                    value={applianceCategory}
