export function V2InquirySectionWithWizard({
  defaultType = "구매 문의",
  fixedType,
  hideTypeSelector = false,
  linkedProduct = null,
  variant = "card",
  onSuccess,
}: {
  defaultType?: InquiryTypeValue;
  fixedType?: InquiryTypeValue;
  hideTypeSelector?: boolean;
  linkedProduct?: LinkedProductContext | null;
  variant?: "card" | "embedded";
  onSuccess?: () => void;
}) {
  const initialType = fixedType || defaultType;
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [inquiryType, setInquiryType] = useState<InquiryTypeValue>(initialType);
  const [selectedCategories, setSelectedCategories] = useState<string[]>([
    linkedProduct?.category || PRODUCT_CATEGORIES[0],
  ]);
  const [selectedChips, setSelectedChips] = useState<string[]>([]);
  const [region, setRegion] = useState("");
  const initialMemo = linkedProduct?.productTitle
    ? linkedProduct.modelName
      ? `${linkedProduct.productTitle} (${linkedProduct.modelName})`
      : linkedProduct.productTitle
    : linkedProduct?.modelName
    ? `모델명: ${linkedProduct.modelName}`
    : "";
  const [memo, setMemo] = useState(
    linkedProduct?.envNote
      ? initialMemo
        ? `[선택한 설치조건: ${linkedProduct.envNote}]\n${initialMemo}`
        : `[선택한 설치조건: ${linkedProduct.envNote}]`
      : initialMemo
  );
  const [analyzingAi, setAnalyzingAi] = useState(false);
  const [basketItems, setBasketItems] = useState<QuoteBasketItem[]>([]);
  const [aiResult, setAiResult] = useState<{
    applianceCategory?: string;
    title?: string;
    modelNumber?: string;
    summaryNote?: string;
  } | null>(null);

  useEffect(() => {
    queueMicrotask(() => {
      setBasketItems(getQuoteBasket());
    });
  }, []);

  useEffect(() => {
    if (!linkedProduct) return;

    queueMicrotask(() => {
      if (
        linkedProduct.category &&
        (PRODUCT_CATEGORIES as readonly string[]).includes(linkedProduct.category)
      ) {
        setSelectedCategories([linkedProduct.category]);
      }

      if (linkedProduct.useBundle) {
        const items = getQuoteBasket();
        if (items.length > 0) {
          const bundleLines = items
            .map(
              (it, idx) =>
                `${idx + 1}. [${it.category}] ${it.title} (수량: ${it.quantity || 1}대)`
            )
            .join("\n");
          setMemo(
            `[견적함 묶음 문의 - 총 ${items.length}개 품목]\n${bundleLines}`
          );
          const cats = Array.from(
            new Set(items.map((it) => it.category).filter(Boolean))
          );
          if (cats.length > 0) {
            setSelectedCategories(cats);
          }
        }
      } else if (linkedProduct.productTitle) {
        const text = linkedProduct.modelName
          ? `${linkedProduct.productTitle} (${linkedProduct.modelName})`
          : linkedProduct.productTitle;
        setMemo((prev) => {
          if (!prev) return text;
          if (!prev.includes(linkedProduct.productTitle!))
            return `${text}\n${prev}`;
          return prev;
        });
      }

      if (linkedProduct.envNote) {
        const envText = `[선택한 설치조건: ${linkedProduct.envNote}]`;
        setMemo((prev) => {
          if (!prev) return envText;
          if (!prev.includes(linkedProduct.envNote!))
            return `${envText}\n${prev}`;
          return prev;
        });
        setSelectedChips((prev) =>
          prev.includes(linkedProduct.envNote!)
            ? prev
            : [...prev, linkedProduct.envNote!]
        );
      }
    });
  }, [linkedProduct]);

  /* 사진 첨부 상태 (최대 3장) */
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [filePreviews, setFilePreviews] = useState<string[]>([]);

  /* 3단계 연락처 상태 */
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");
  const [agreed, setAgreed] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  /* 촬영 참고 가이드 토글 및 확대 보기 상태 */
  const [showGuide, setShowGuide] = useState(true);
  const [zoomGuide, setZoomGuide] = useState(false);
  const guideInfo =
    PHOTO_GUIDE_DATA[inquiryType] || PHOTO_GUIDE_DATA["내 물건 팔기"];

  const toggleCategory = (cat: string) => {
    setSelectedCategories((prev) =>
      prev.includes(cat)
        ? prev.length > 1
          ? prev.filter((c) => c !== cat)
          : prev
        : [...prev, cat]
    );
  };

  const toggleChip = (chip: string) => {
    setSelectedChips((prev) =>
      prev.includes(chip) ? prev.filter((c) => c !== chip) : [...prev, chip]
    );
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const picked = Array.from(e.target.files ?? []);
    e.target.value = "";
    if (!picked.length) return;

    const remaining = MAX_PHOTOS - selectedFiles.length;
    if (remaining <= 0) {
      toast.error(`사진은 최대 ${MAX_PHOTOS}장까지 첨부할 수 있습니다.`);
      return;
    }

    const { ok, error } = validateImageFiles(picked, remaining);
    if (error) toast.error(error);
    if (ok.length === 0) return;

    setSelectedFiles((prev) => [...prev, ...ok]);
    setFilePreviews((prev) => [
      ...prev,
      ...ok.map((f) => URL.createObjectURL(f)),
    ]);
  };

  const handleRemoveFile = (index: number) => {
    URL.revokeObjectURL(filePreviews[index]);
    setSelectedFiles((prev) => prev.filter((_, i) => i !== index));
    setFilePreviews((prev) => prev.filter((_, i) => i !== index));
  };

  const handleAiPhotoAnalyze = async () => {
    if (selectedFiles.length === 0 || analyzingAi) return;
    setAnalyzingAi(true);
    const toastId = toast.loading(
      "첨부된 사진을 AI가 분석하여 품목과 모델명을 추출 중입니다..."
    );
    try {
      const formData = new FormData();
      formData.append("inquiryType", inquiryType);
      formData.append("userTitle", memo);
      formData.append("userDescription", memo);
      formData.append("userRegion", region);

      for (const file of selectedFiles.slice(0, MAX_PHOTOS)) {
        const compressedBlob = await compressImage(file, 1280, 0.8);
        const optimizedFile = new File([compressedBlob], file.name, {
          type: "image/jpeg",
        });
        formData.append("files", optimizedFile);
      }

      const res = await fetch("/api/analyze-inquiry", {
        method: "POST",
        body: formData,
      });

      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data.success) {
        throw new Error(data.error || "AI 사진 분석에 실패했습니다.");
      }

      setAiResult({
        applianceCategory: data.applianceCategory,
        title: data.title,
        modelNumber: data.modelNumber,
        summaryNote:
          data.summaryNote ||
          (data.estimatedYear ? `연식: ${data.estimatedYear}` : undefined),
      });

      if (
        data.applianceCategory &&
        (PRODUCT_CATEGORIES as readonly string[]).includes(data.applianceCategory)
      ) {
        setSelectedCategories((prev) =>
          prev.includes(data.applianceCategory)
            ? prev
            : [data.applianceCategory, ...prev]
        );
      }

      const aiDetails: string[] = [];
      if (data.title) aiDetails.push(data.title);
      if (data.modelNumber) aiDetails.push(`모델명: ${data.modelNumber}`);
      if (data.summaryNote) aiDetails.push(data.summaryNote);
      else if (data.estimatedYear) aiDetails.push(`연식: ${data.estimatedYear}`);
      if (aiDetails.length > 0) {
        const aiText = `[AI 사진 판독: ${aiDetails.join(" / ")}]`;
        setMemo((prev) => (prev ? `${aiText}\n${prev}` : aiText));
      }

      toast.success(
        "AI 사진 판독 완료! 품목과 상세 정보가 자동으로 채워졌습니다.",
        { id: toastId }
      );
    } catch (err: unknown) {
      toast.error(
        err instanceof Error ? err.message : "AI 사진 분석에 실패했습니다.",
        { id: toastId }
      );
    } finally {
      setAnalyzingAi(false);
    }
  };

  const handleWizardSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;
    if (!name.trim()) {
      toast.error("성함 또는 상호명을 입력해 주세요.");
      return;
    }
    if (!isValidPhone(phone)) {
      toast.error("올바른 연락처를 입력해 주세요.");
      return;
    }
    if (password.trim().length < 4) {
      toast.error("조회용 비밀번호 4자리 이상을 입력해 주세요.");
      return;
    }
    if (!agreed) {
      toast.error("개인정보 수집·이용에 동의해 주세요.");
      return;
    }

    setSubmitting(true);
    try {
      // 1. 사진 업로드 처리 (선택 첨부된 파일이 있는 경우)
      let uploadedUrls: string[] = [];
      if (selectedFiles.length > 0) {
        uploadedUrls = await compressAndUploadProductImages(selectedFiles, {
          maxWidth: 1400,
          quality: 0.8,
          bucket: STORAGE_BUCKETS.inquiries,
          prefix: "inq",
        });
      }

      // 2. 구조화 본문 생성
      const catSummary = selectedCategories.join(" · ");
      const autoTitle = `[${inquiryType}] ${catSummary} 견적 신청`;
      const chipLine =
        selectedChips.length > 0
          ? `• 선택 조건: ${selectedChips.join(", ")}`
          : "";
      const bodyContent = [
        `• 선택 품목: ${catSummary}`,
        chipLine,
        memo.trim() ? `• 상세 메모: ${memo.trim()}` : "",
      ]
        .filter(Boolean)
        .join("\n");

      const structuredDescription = formatStructuredInquiryDescription({
        inquiryType,
        customerContent: bodyContent,
        applianceCategory: selectedCategories[0],
        region: region.trim() || "대전/충청",
        linkedProductUrl: linkedProduct?.productId
          ? `${STORE.url}/${linkedProduct.productId}`
          : undefined,
        modelNumber: linkedProduct?.modelName || undefined,
      });

      const res = await fetch("/api/inquiries", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: name.trim(),
          phone: phone.trim(),
          password: password.trim(),
          inquiry_type: inquiryType,
          category: autoTitle,
          region: region.trim() || "대전/기타",
          description: structuredDescription,
          images: uploadedUrls,
          is_notice: false,
        }),
      });

      const json = await res.json().catch(() => ({}));
      if (!res.ok || !json.success) {
        throw new Error(json.error || "접수 중 오류가 발생했습니다.");
      }

      trackEvent("submit_inquiry_success", {
        inquiry_type: inquiryType,
        has_photos: uploadedUrls.length > 0,
      });

      toast.success(
        inquiryType === "내 물건 팔기"
          ? "매입 견적 신청이 정상 접수되었습니다!"
          : "견적 상담 접수가 정상 완료되었습니다!"
      );
      setStep(1);
      setMemo("");
      setSelectedFiles([]);
      setFilePreviews([]);
      onSuccess?.();
    } catch (err: unknown) {
      toast.error(
        err instanceof Error ? err.message : "접수에 실패했습니다."
      );
    } finally {
      setSubmitting(false);
    }
  };

  const isSell = inquiryType === "내 물건 팔기";

  return (
    <div className={variant === "embedded" ? "" : "space-y-4"}>
      <form
        onSubmit={handleWizardSubmit}
        className={
          variant === "embedded"
            ? "space-y-5"
            : "rounded-xl border border-[#E5E2DC] bg-white p-4 sm:p-6 space-y-5 shadow-2xs"
        }
      >
        {/* 모던 스텝퍼(Stepper) UI */}
        <div className="space-y-3 pb-2 border-b border-[#E5E2DC]">
          <div className="flex items-center justify-between text-hb-xs font-extrabold">
            <span className="text-[#D9531E]">{step}단계 / 3단계</span>
            <span className="text-[#646E7E]">
              {step === 1
                ? isSell
                  ? "처분하실 품목을 선택해 주세요"
                  : "상담 목적과 품목을 선택해 주세요"
                : step === 2
                ? "제품 사진 첨부 및 촬영 가이드 확인 (생략 가능)"
                : "수거·현장 조건과 연락처를 입력해 주세요"}
            </span>
          </div>

          {/* 3단계 스텝퍼 번호/체크 아이콘 인디케이터 */}
          <div className="grid grid-cols-3 gap-2">
            {[
              { num: 1, label: "상담 유형·품목" },
              { num: 2, label: "사진·가이드" },
              { num: 3, label: "현장조건·접수" },
            ].map((s) => {
              const isPast = step > s.num;
              const isCurrent = step === s.num;
              return (
                <div
                  key={s.num}
                  className={`flex items-center gap-2 rounded-lg p-2 transition-all ${
                    isCurrent
                      ? "bg-[#0E1A2B] text-white"
                      : isPast
                      ? "bg-[#FFF5F0] text-[#D9531E] border border-[#FED7AA]"
                      : "bg-[#F7F5F0] text-[#858076]"
                  }`}
                >
                  <span
                    className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-hb-xs font-bold ${
                      isCurrent
                        ? "bg-[#FF8A50] text-[#0E1A2B]"
                        : isPast
                        ? "bg-[#D9531E] text-white"
                        : "bg-[#E5E2DC] text-[#646E7E]"
                    }`}
                  >
                    {isPast ? (
                      <Icon d={ICON.check} className="w-3.5 h-3.5" />
                    ) : (
                      s.num
                    )}
                  </span>
                  <span className="truncate text-hb-xs font-bold">
                    {s.label}
                  </span>
                </div>
              );
            })}
          </div>

          <div className="h-1.5 w-full overflow-hidden rounded-full bg-[#F0EDE7]">
            <div
              style={{ width: `${(step / 3) * 100}%` }}
              className="h-full bg-[#0E1A2B] transition-all duration-300"
            />
          </div>
        </div>

        {/* STEP 1: 상담 유형 & 품목 선택 */}
        {step === 1 && (
          <div className="space-y-4">
            {basketItems.length > 0 && (
              <div className="rounded-lg border border-[#3B82F6]/30 bg-[#EFF6FF] p-3 text-hb-xs text-[#1E3A8A] flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center gap-1.5">
                  <Icon d={ICON.bag} className="w-4 h-4 text-[#2563EB] shrink-0" />
                  <span>
                    견적함에 담긴 관심 매물 {basketItems.length}건을 문의 내용에 자동 반영하기
                  </span>
                </div>
                <button
                  type="button"
                  onClick={() => {
                    const summary = formatQuoteBasketSummary(basketItems);
                    if (summary.hasCommercialItem) {
                      setInquiryType("대량·업소용 상담");
                    }
                    if (summary.autoDescription) {
                      setMemo(summary.autoDescription);
                    }
                    const cats = Array.from(
                      new Set(basketItems.map((it) => it.category).filter(Boolean))
                    );
                    if (cats.length > 0) {
                      setSelectedCategories(cats);
                    }
                    toast.success("견적함 매물이 문의 내용에 자동 반영되었습니다.");
                  }}
                  className="hb-btn-outline h-7 px-2.5 text-hb-xs font-bold bg-white text-[#1D4ED8] hover:bg-blue-50 border-[#93C5FD] cursor-pointer"
                >
                  견적함 자동 반영
                </button>
              </div>
            )}

            {!hideTypeSelector && !fixedType && (
              <div>
                <span className="hb-label mb-2">1. 어떤 상담이 필요하신가요?</span>
                <div className="grid grid-cols-2 gap-2">
                  {INQUIRY_TYPES.map((t) => {
                    const active = inquiryType === t;
                    return (
                      <button
                        key={t}
                        type="button"
                        onClick={() => {
                          setInquiryType(t);
                          setSelectedChips([]);
                        }}
                        className={`h-12 rounded-xl border px-3 text-hb-sm font-extrabold transition-all cursor-pointer ${
                          active
                            ? "border-[#0E1A2B] bg-[#0E1A2B] text-white shadow-2xs"
                            : "border-[#E5E2DC] bg-[#FAF9F7] text-[#0E1A2B] hover:border-[#0E1A2B]"
                        }`}
                      >
                        {t === "내 물건 팔기" ? "가전 팔기(방문매입)" : t}
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            <div>
              <span className="hb-label mb-2">
                {hideTypeSelector || fixedType
                  ? "1. 처분하실 품목을 모두 선택해 주세요 (복수 선택)"
                  : "2. 해당되는 품목을 모두 선택해 주세요 (복수 선택)"}
              </span>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {PRODUCT_CATEGORIES.map((cat) => {
                  const active = selectedCategories.includes(cat);
                  return (
                    <button
                      key={cat}
                      type="button"
                      onClick={() => toggleCategory(cat)}
                      className={`flex h-11 items-center justify-between rounded-lg border px-3 text-hb-sm font-bold transition-all cursor-pointer ${
                        active
                          ? "border-[#D9531E] bg-[#FFF5F0] text-[#D9531E] ring-1 ring-[#D9531E]"
                          : "border-[#E5E2DC] bg-white text-[#3E4756] hover:border-[#0E1A2B]"
                      }`}
                    >
                      <span>{cat}</span>
                      <Icon
                        d={active ? ICON.check : ICON.plus}
                        className="w-3.5 h-3.5 shrink-0"
                      />
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="pt-2 flex justify-end border-t border-[#E5E2DC]">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="hb-btn-primary h-11 px-7 text-hb-sm w-full sm:w-auto"
              >
                <span>다음 단계 (사진 첨부)</span>
                <Icon d={ICON.arrow} className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* STEP 2: 사진 첨부(선택) + 현장 조건 칩 + 지역 입력 */}
        {step === 2 && (
          <div className="space-y-4">
            {/* 사진 첨부 섹션 (한 화면 직접 내장) */}
            <div>
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="hb-label">
                  {hideTypeSelector || fixedType
                    ? "2. 제품 사진 첨부 (선택, 최대 3장)"
                    : "3. 제품 사진 첨부 (선택, 최대 3장)"}
                </span>
                <span className="text-hb-xs text-[#646E7E]">
                  {selectedFiles.length} / {MAX_PHOTOS}장
                </span>
              </div>

              <div className="flex flex-wrap items-center gap-3">
                {filePreviews.map((src, i) => (
                  <div
                    key={src}
                    className="relative aspect-square w-20 sm:w-24 overflow-hidden rounded-lg border border-[#E5E2DC] bg-[#F0EDE7] shrink-0"
                  >
                    <SafeImg
                      src={src}
                      alt={`선택 사진 ${i + 1}`}
                      className="h-full w-full object-cover"
                    />
                    <button
                      type="button"
                      onClick={() => handleRemoveFile(i)}
                      aria-label="사진 제거"
                      className="absolute right-1 top-1 grid h-5 w-5 place-items-center rounded-full bg-black/75 text-white hover:bg-red-600 transition-colors"
                    >
                      <Icon d={ICON.close} className="w-3 h-3" />
                    </button>
                  </div>
                ))}

                {selectedFiles.length < MAX_PHOTOS && (
                  <label className="flex aspect-square w-20 sm:w-24 cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-[#D7D2C8] bg-[#FAF9F7] text-hb-xs font-semibold text-[#667085] hover:border-[#D9531E] hover:text-[#D9531E] transition-colors shrink-0">
                    <Icon d={ICON.camera} className="w-5 h-5 text-[#858076]" />
                    <span className="mt-1">+ 사진 추가</span>
                    <input
                      type="file"
                      accept="image/*"
                      multiple
                      className="hidden"
                      onChange={handleFileChange}
                    />
                  </label>
                )}
              </div>

              {selectedFiles.length > 0 && (
                <div className="mt-2.5 space-y-2">
                  <button
                    type="button"
                    onClick={handleAiPhotoAnalyze}
                    disabled={analyzingAi}
                    className="inline-flex items-center gap-1.5 rounded-lg border border-[#3B82F6]/30 bg-[#EFF6FF] px-3.5 py-2 text-hb-xs font-bold text-[#1D4ED8] hover:bg-[#DBEAFE] transition-colors disabled:opacity-50 cursor-pointer shadow-2xs"
                  >
                    <Icon d={ICON.sparkles} className="w-3.5 h-3.5 shrink-0" />
                    <span>
                      {analyzingAi
                        ? "AI 사진 판독 및 품목 분석 중..."
                        : "AI 사진 판독으로 품목·모델명 자동입력"}
                    </span>
                  </button>

                  {aiResult && (
                    <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-2.5 text-hb-xs text-emerald-800 flex items-start gap-2">
                      <Icon
                        d={ICON.check}
                        className="w-4 h-4 text-emerald-600 shrink-0 mt-0.5"
                      />
                      <div className="leading-relaxed">
                        <strong className="font-bold text-emerald-900">
                          AI 판독 결과 적용됨:
                        </strong>{" "}
                        {[
                          aiResult.applianceCategory,
                          aiResult.title,
                          aiResult.modelNumber,
                          aiResult.summaryNote,
                        ]
                          .filter(Boolean)
                          .join(" · ")}
                      </div>
                    </div>
                  )}
                </div>
              )}

              <p className="mt-2 text-hb-xs text-[#646E7E]">
                제품 전면 또는 모델명 명판 스티커 사진을 첨부하시면 가장 신속하고 정확한 견적을 받으실 수 있습니다. (생략 가능)
              </p>

              {/* 권장 촬영 참고 사진 가이드 (실제 예시 그래픽 + 3단계 요약 카드 + 라이트박스 확대) */}
              <div className="mt-3 overflow-hidden rounded-xl border border-[#E5E2DC] bg-[#FAF9F7]">
                <div className="flex items-center justify-between px-3.5 py-2.5 bg-white border-b border-[#E5E2DC]">
                  <div className="flex items-center gap-1.5 text-hb-xs font-bold text-[#0E1A2B]">
                    <Icon d={ICON.camera} className="w-3.5 h-3.5 text-[#D9531E]" />
                    <span>권장 촬영 참고 사진</span>
                    <span className="text-[#858076] font-normal hidden sm:inline">
                      · {guideInfo.subtitle}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => setZoomGuide(true)}
                      className="hb-btn-outline h-7 px-2.5 text-hb-xs font-bold text-[#0E1A2B] hover:border-[#0E1A2B]"
                    >
                      크게 보기
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowGuide((prev) => !prev)}
                      className="rounded p-1 text-[#646E7E] hover:text-[#0E1A2B]"
                      aria-label={showGuide ? "가이드 접기" : "가이드 펼치기"}
                    >
                      <Icon
                        d={showGuide ? ICON.up : ICON.down}
                        className="w-4 h-4"
                      />
                    </button>
                  </div>
                </div>

                {showGuide && (
                  <div>
                    {/* 실제 촬영 예시 배너 이미지 */}
                    <button
                      type="button"
                      onClick={() => setZoomGuide(true)}
                      className="group relative block w-full overflow-hidden bg-white text-left focus:outline-none cursor-zoom-in border-b border-[#E5E2DC]"
                      aria-label="권장 촬영 예시 사진 원본 크게 보기"
                    >
                      <SafeImg
                        src={guideInfo.image}
                        alt="권장 촬영 예시 사진 가이드"
                        className="w-full max-h-[170px] sm:max-h-[200px] object-contain mx-auto transition-transform duration-200 group-hover:scale-[1.01]"
                      />
                    </button>

                    {/* 3단계 촬영 포인트 안내 카드 */}
                    <ol className="grid grid-cols-1 sm:grid-cols-3 gap-2 p-3 bg-[#FAF9F7] text-hb-xs">
                      {guideInfo.steps.map((g) => (
                        <li
                          key={g.step}
                          className="flex items-start gap-2 rounded-lg bg-white p-2.5 border border-[#E5E2DC]"
                        >
                          <span className="shrink-0 rounded bg-[#0E1A2B] px-1.5 py-0.5 text-hb-xs font-extrabold text-white">
                            {g.step}
                          </span>
                          <div className="min-w-0 flex-1">
                            <strong className="font-bold text-[#0E1A2B] block">
                              {g.title}
                            </strong>
                            <span className="text-[#646E7E] leading-relaxed block mt-0.5">
                              {g.desc}
                            </span>
                          </div>
                        </li>
                      ))}
                    </ol>

                    {/* 하단 팁 */}
                    <div className="px-3 pb-3 pt-0">
                      <p className="rounded-lg bg-white p-2.5 border border-[#E5E2DC] text-hb-xs text-[#4B5260] leading-relaxed">
                        {guideInfo.tip}
                      </p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="pt-2 flex items-center justify-between gap-2 border-t border-[#E5E2DC]">
              <button
                type="button"
                onClick={() => setStep(1)}
                className="hb-btn-outline h-11 px-5 text-hb-sm"
              >
                ← 이전
              </button>
              <button
                type="button"
                onClick={() => setStep(3)}
                className="hb-btn-primary h-11 px-7 text-hb-sm"
              >
                <span>다음 단계 (조건 및 연락처 입력)</span>
                <Icon d={ICON.arrow} className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* STEP 3: 현장 조건 + 지역/메모 + 연락처 입력 및 완료 */}
        {step === 3 && (
          <div className="space-y-4">
            <div className="rounded-lg border border-[#E5E2DC] bg-[#FAF9F7] p-3 text-hb-xs text-[#3E4756] flex flex-wrap items-center justify-between gap-1.5">
              <div>
                <strong className="text-[#0E1A2B]">선택 요약:</strong> [{inquiryType}] {selectedCategories.join(", ")}
                {selectedFiles.length > 0
                  ? ` · 사진 ${selectedFiles.length}장 첨부됨`
                  : " · 사진 미첨부"}
              </div>
              <button
                type="button"
                onClick={() => setStep(2)}
                className="text-hb-xs text-[#646E7E] underline hover:text-[#0E1A2B]"
              >
                사진 수정
              </button>
            </div>

            {/* 1. 현장 조건 칩 */}
            <div>
              <span className="hb-label mb-2">
                {isSell
                  ? "1. 해당되는 수거·현장 조건을 선택해 주세요 (선택)"
                  : "1. 해당되는 현장·배송 조건을 선택해 주세요 (선택)"}
              </span>
              <div className="flex flex-wrap gap-2">
                {WIZARD_ENV_CHIPS[inquiryType].map((chip) => {
                  const active = selectedChips.includes(chip);
                  return (
                    <button
                      key={chip}
                      type="button"
                      onClick={() => toggleChip(chip)}
                      className={`h-11 inline-flex items-center gap-1.5 rounded-lg border px-3 text-hb-sm font-bold transition-all cursor-pointer ${
                        active
                          ? "border-[#D9531E] bg-[#FFF5F0] text-[#D9531E] ring-1 ring-[#D9531E]"
                          : "border-[#E5E2DC] bg-[#FAF9F7] text-[#3E4756] hover:border-[#0E1A2B]"
                      }`}
                    >
                      <Icon
                        d={active ? ICON.check : ICON.plus}
                        className="w-3.5 h-3.5 shrink-0"
                      />
                      <span>{chip}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* 2. 지역 및 간단 메모 */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="hb-label">
                  {isSell ? "2. 방문 수거 지역 (구/동 단위 권장)" : "2. 배송/설치 지역 (동 단위 권장)"}
                </label>
                <input
                  type="text"
                  value={region}
                  onChange={(e) => setRegion(e.target.value)}
                  placeholder="예: 대전 중구 중촌동 / 서구 둔산동"
                  className="hb-input mt-1 h-11"
                />
              </div>
              <div>
                <label className="hb-label">
                  간단 메모 (희망 일정·세부 모델 등)
                </label>
                <input
                  type="text"
                  value={memo}
                  onChange={(e) => setMemo(e.target.value)}
                  placeholder="예: 금요일 오후 희망 / 삼성 4도어 냉장고"
                  className="hb-input mt-1 h-11"
                />
              </div>
            </div>

            {/* 3. 연락처 및 신청자 정보 */}
            <div className="pt-2 border-t border-[#E5E2DC] space-y-2">
              <span className="hb-label">3. 신청자 정보 및 연락처 *</span>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div>
                  <label className="hb-label text-[#646E7E]">성함 / 상호명 *</label>
                  <input
                    type="text"
                    required
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    placeholder="홍길동 / 한밭식당"
                    className="hb-input mt-1 h-11"
                  />
                </div>
                <div>
                  <label className="hb-label text-[#646E7E]">연락처 *</label>
                  <input
                    type="tel"
                    required
                    value={phone}
                    onChange={(e) => setPhone(formatPhone(e.target.value))}
                    placeholder="010-0000-0000"
                    className="hb-input mt-1 h-11 tabular-nums"
                  />
                </div>
                <div>
                  <label className="hb-label text-[#646E7E]">조회 비밀번호(4자+) *</label>
                  <input
                    type="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="내 글 확인용"
                    className="hb-input mt-1 h-11"
                  />
                </div>
              </div>
            </div>

            <label className="flex items-center gap-2 text-hb-xs text-[#4B5260] cursor-pointer select-none">
              <input
                type="checkbox"
                checked={agreed}
                onChange={(e) => setAgreed(e.target.checked)}
                className="h-4 w-4 rounded border-[#CFCAC0] accent-[#0E1A2B]"
              />
              <span>상담 안내를 위한 개인정보 수집·이용에 동의합니다.</span>
            </label>

            <div className="flex flex-wrap items-center justify-between gap-3 pt-2 border-t border-[#E5E2DC]">
              <button
                type="button"
                onClick={() => setStep(2)}
                className="hb-btn-outline h-11 px-4 text-hb-sm"
              >
                ← 이전 (사진)
              </button>

              <div className="flex flex-wrap items-center gap-2 ml-auto">
                <a
                  href={smsHref(
                    STORE.mobile,
                    `[한밭중고전자 ${inquiryType}] 품목: ${selectedCategories.join(
                      ", "
                    )} / 조건: ${selectedChips.join(", ")} 문의드립니다.`
                  )}
                  className="hb-btn-outline h-11 px-4 text-hb-sm"
                >
                  <Icon d={ICON.chat} className="w-3.5 h-3.5 text-[#D9531E]" />
                  <span>문자로 바로 전송</span>
                </a>
                <button
                  type="submit"
                  disabled={submitting}
                  className="hb-btn-accent h-11 px-7 text-hb-sm font-extrabold"
                >
                  {submitting
                    ? "접수 중..."
                    : isSell
                    ? "매입 견적 신청 완료하기"
                    : "견적 문의 완료하기"}
                </button>
              </div>
            </div>
          </div>
        )}
      </form>

      {zoomGuide && (
        <Modal
          label="권장 촬영 참고 사진 가이드"
          onClose={() => setZoomGuide(false)}
          panelClassName="max-w-3xl w-full"
          overlayClassName="z-[70]"
        >
          <div className="overflow-hidden rounded-xl border border-[#E5E2DC] bg-white shadow-2xl">
            <div className="flex items-center justify-between border-b border-[#E5E2DC] px-5 py-3.5 bg-[#0E1A2B] text-white">
              <div className="flex items-center gap-2">
                <Icon d={ICON.camera} className="w-4 h-4 text-[#D9531E]" />
                <h3 className="text-hb-sm font-bold text-white">
                  권장 촬영 참고 사진 가이드
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setZoomGuide(false)}
                aria-label="닫기"
                className="rounded p-1 text-white/80 hover:bg-white/10 hover:text-white"
              >
                <Icon d={ICON.close} className="h-5 w-5" />
              </button>
            </div>
            <div className="max-h-[80vh] overflow-y-auto bg-[#FAF9F7] p-4 flex flex-col items-center gap-3">
              <SafeImg
                src={guideInfo.image}
                alt="권장 촬영 참고 사진 가이드 원본"
                className="max-h-[65vh] w-auto object-contain rounded-lg border border-[#E5E2DC] bg-white shadow-xs"
              />
              <p className="text-hb-xs text-[#646E7E] text-center max-w-lg leading-relaxed">
                {guideInfo.tip}
              </p>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}


// 파일 경로: components/products/product-card.tsx
"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import toast from "react-hot-toast";
import {
  extractModelName,
  extractSpecCapsules,
  formatProductPrice,
  getQuoteBasket,
  hasProductPrice,
  isProductSold,
  normalizeProductCategory,
  QUOTE_BASKET_EVENT,
  splitImages,
  toggleQuoteBasketItem,
  trackEvent,
} from "../../lib/site";
import { Icon, ICON, SafeImg } from "../../lib/ui";
import { ProductStatusBadge } from "./product-status-badge";
import { ModernApplianceIcon } from "../ui/modern-icons";

export interface ProductItem {
  id: string;
  title: string;
  category: string | null;
  description?: string | null;
  image_url: string | null;
  price: number | null;
  status: string | null;
  condition_grade?: string | null;
  created_at: string;
  views?: number | null;
}

export function ProductTrustMicroStrip({
  category,
  className = "",
}: {
  category?: string | null;
  className?: string;
}) {
  const normalizedCategory = normalizeProductCategory(category);
  const isHvac = normalizedCategory === "에어컨/냉난방기";
  const isMajorAppliance =
    normalizedCategory === "냉장고" || normalizedCategory === "세탁기/건조기";

  const warrantyHighlight = isHvac
    ? "에어컨류 계약조건별 최대 8개월"
    : isMajorAppliance
    ? "주요 가전 계약조건별 최대 4개월"
    : "품목 및 계약조건에 따라 협의 적용";

  const items = [
    {
      step: "01",
      title: "분해 세척·작동 점검",
      desc:
        isHvac || isMajorAppliance
          ? "입고 후 작동 테스트 및 고압 세척 완료"
          : "입고 후 전문 검수 및 클리닝 점검 완료",
      highlight: null,
      icon: "sparkle" as const,
      color: "text-[#0D9488]",
      badge: "bg-[#F0FDFA] text-[#0F766E] border-[#CCFBF1]",
    },
    {
      step: "02",
      title: "사후 무상 A/S 보증",
      desc: "계약 조건에 따라 보증 기간 차등 적용",
      highlight: warrantyHighlight,
      icon: "shield" as const,
      color: "text-[#D9531E]",
      badge: "bg-[#FFF5F0] text-[#D9531E] border-[#FADCD0]",
    },
    {
      step: "03",
      title: "세금계산서·직배송",
      desc: "사업자 부가세 증빙 및 직영 배송·설치 지원",
      highlight: null,
      icon: "tax" as const,
      color: "text-[#0284C7]",
      badge: "bg-[#F0F9FF] text-[#0369A1] border-[#BAE6FD]",
    },
  ] as const;

  return (
    <section
      aria-label="한밭중고전자 핵심 거래 보증 안내"
      className={`border-y border-[#E5E2DC] bg-[#FAF9F7] ${className}`}
    >
      <div className="grid grid-cols-1 sm:grid-cols-3 divide-y sm:divide-y-0 sm:divide-x divide-[#E5E2DC]">
        {items.map((item) => (
          <div
            key={item.title}
            className="flex flex-col justify-between px-4 py-3.5"
          >
            <div>
              <div className="flex items-center gap-2.5 text-hb-xs sm:text-hb-sm font-bold tracking-[-0.01em] text-[#0E1A2B]">
                <ModernApplianceIcon name={item.icon} className="w-8 h-8 sm:w-9 sm:h-9 shrink-0" />
                <span className={`font-mono text-hb-xs font-extrabold ${item.color}`}>
                  {item.step}
                </span>
                <span className="truncate">{item.title}</span>
              </div>
              <p className="mt-1.5 text-hb-xs leading-[1.45] text-[#434B59] break-keep">
                {item.desc}
              </p>
            </div>
            {item.highlight && (
              <span className={`mt-1 inline-block text-hb-xs font-semibold ${item.color} break-keep`}>
                · {item.highlight}
              </span>
            )}
          </div>
        ))}
      </div>
    </section>
  );
}

export function ProductCard({
  product,
  onSelect,
  onQuickView,
  isSelectMode = false,
  isSelected = false,
  isAdmin = false,
  onDelete,
}: {
  product: ProductItem;
  onSelect?: (product: ProductItem) => void;
  onQuickView?: (product: ProductItem) => void;
  isSelectMode?: boolean;
  isSelected?: boolean;
  isAdmin?: boolean;
  onDelete?: (id: string) => void;
}) {
  const images = splitImages(product.image_url);
  const sold = isProductSold(product.status);
  const categoryLabel = normalizeProductCategory(product.category);
  const priced = hasProductPrice(product.price);
  const priceText = formatProductPrice(product.price, categoryLabel);
  const modelName = extractModelName(product.description, product.title);
  const specCapsules = extractSpecCapsules(
    product.title,
    product.description,
    3
  );

  const [inBasket, setInBasket] = useState(false);

  useEffect(() => {
    const sync = () => {
      setInBasket(getQuoteBasket().some((x) => x.id === product.id));
    };
    sync();
    window.addEventListener(QUOTE_BASKET_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(QUOTE_BASKET_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [product.id]);

  const handleToggleBasket = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const res = toggleQuoteBasketItem({
      id: product.id,
      title: product.title,
      category: categoryLabel,
      price: product.price,
      status: product.status,
      conditionGrade: product.condition_grade,
      description: product.description,
      modelName,
      imageUrl: images[0] || null,
      quantity: 1,
    });
    if (res.limitReached) {
      toast.error("견적함에는 최대 8개까지 담을 수 있습니다.");
    } else if (res.added) {
      trackEvent("add_to_quote_basket", {
        category: categoryLabel,
        location: "card",
      });
      toast.success("관심 매물 견적함에 담았습니다.");
    } else {
      toast("견적함에서 제외했습니다.");
    }
  };

  const specSummaryText =
    specCapsules.length > 0
      ? specCapsules.join(" · ")
      : "분해 세척 · 작동 검수 완료";

  const cardInner = (
    <article
      className={`group relative flex h-full flex-col overflow-hidden rounded-2xl bg-white transition-all duration-200 ${
        isSelected
          ? "ring-2 ring-[#D9531E] bg-[#FFFDFB] shadow-card-hover"
          : "hb-surface-card hover:border-[#0E1A2B]/40 hover:shadow-card-hover"
      }`}
    >
      {/* 1. 시원시원한 대형 풀블리드 사진 (스튜디오 조명 백드롭 & 내부 액자 링) */}
      <div className="relative aspect-[4/3] w-full overflow-hidden hb-studio-backdrop ring-1 ring-inset ring-[#0E1A2B]/[0.05]">
        <SafeImg
          src={images[0]}
          alt={product.title}
          className={`h-full w-full object-cover transition-transform duration-500 group-hover:scale-105 ${
            sold ? "grayscale opacity-65" : ""
          }`}
        />

        {sold && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0E1A2B]/45">
            <span className="rounded bg-[#0E1A2B]/95 px-3.5 py-1.5 text-hb-xs font-bold tracking-widest text-white">
              판매완료
            </span>
          </div>
        )}

        {/* 좌상단 판매 상태 배지 & 외관 상태 등급 */}
        {isSelectMode ? (
          <div
            className={`absolute left-3 top-3 z-20 flex h-6 w-6 items-center justify-center rounded border transition-colors ${
              isSelected
                ? "border-[#D9531E] bg-[#D9531E] text-white"
                : "border-[#858076] bg-white/95 text-transparent"
            }`}
          >
            <Icon d={ICON.check} className="h-3.5 w-3.5" />
          </div>
        ) : (
          <div className="absolute left-2.5 top-2.5 z-10 flex items-center gap-1.5">
            <ProductStatusBadge
              status={product.status}
              createdAt={product.created_at}
              showNew={false}
            />
            {product.condition_grade && (
              <span className="rounded bg-white/90 backdrop-blur-xs px-2 py-0.5 text-hb-xs font-extrabold text-[#D9531E] shadow-2xs border border-[#E5E2DC]/80">
                {product.condition_grade}
              </span>
            )}
          </div>
        )}

        {/* 좌하단 플로팅 글래스 미리보기 / 관리자 빠른 수정 캡슐 */}
        {!isSelectMode && onQuickView && (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onQuickView(product);
            }}
            title={isAdmin ? "관리자 수정" : "상품 미리보기"}
            aria-label={`${product.title} ${isAdmin ? "수정" : "미리보기"}`}
            className="absolute bottom-2.5 left-2.5 z-20 inline-flex items-center gap-1 rounded-full bg-white/90 backdrop-blur-md border border-[#0E1A2B]/15 px-2.5 py-1 text-hb-xs font-bold text-[#0E1A2B] shadow-xs hover:bg-[#0E1A2B] hover:text-white transition-colors cursor-pointer active:scale-95"
          >
            <Icon
              d={isAdmin ? ICON.pen : ICON.search}
              className="w-3 h-3 text-[#D9531E]"
            />
            <span>{isAdmin ? "수정" : "미리보기"}</span>
          </button>
        )}

        {/* 우하단 다중 사진 수량 표시 */}
        {!sold && images.length > 1 && (
          <span className="pointer-events-none absolute bottom-2 right-2 z-10 inline-flex items-center gap-1 rounded bg-[#0E1A2B]/75 px-2 py-0.5 text-hb-xs font-semibold text-white tabular-nums backdrop-blur-xs">
            <Icon d={ICON.image} className="w-3 h-3 text-white/80" />
            +{images.length - 1}
          </span>
        )}

        {isAdmin && !isSelectMode && onDelete && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
              onDelete(product.id);
            }}
            title="상품 삭제"
            aria-label={`${product.title} 삭제`}
            className="absolute right-2.5 top-2.5 z-20 flex h-7 w-7 items-center justify-center rounded border border-red-200 bg-white/95 text-red-600 shadow hover:bg-red-50 transition-colors"
          >
            <Icon d={ICON.close} className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* 2. 쇼룸 에디토리얼 정보 영역 (불필요한 중첩 박스 제거 · 가격과 제품명 중심) */}
      <div className="flex flex-1 flex-col justify-between p-3.5 sm:p-4 bg-white border-t border-[#ECE9E2]">
        <div>
          {/* 상단 메타: 카테고리 + 모델명 */}
          <div className="flex items-center justify-between gap-2 text-hb-xs">
            <span className="font-bold text-[#D9531E] truncate">
              {categoryLabel}
            </span>
            {modelName ? (
              <span
                className="shrink-0 max-w-[55%] truncate font-mono text-hb-xs text-[#646E7E]"
                title={modelName}
              >
                {modelName}
              </span>
            ) : product.condition_grade ? (
              <span className="shrink-0 font-semibold text-[#646E7E]">
                {product.condition_grade}
              </span>
            ) : null}
          </div>

          {/* 상품명 (2줄 말줄임 + 하단 글자 잘림 방지 여유고 및 그리드 정렬용 최소 높이) */}
          <h3
            className={`mt-1 line-clamp-2 min-h-[2.85rem] sm:min-h-[3.25rem] text-hb-sm sm:text-hb-base font-bold leading-[1.4] tracking-[-0.015em] transition-colors break-keep pb-0.5 ${
              sold
                ? "text-[#646E7E]"
                : "text-[#0E1A2B] group-hover:text-[#D9531E]"
            }`}
          >
            {product.title}
          </h3>

          {/* 사양 요약 (모바일/데스크톱 마이크로 스펙 칩) */}
          {specCapsules.length > 0 ? (
            <div className="mt-1.5 flex flex-wrap gap-1 overflow-hidden">
              {specCapsules.map((cap) => (
                <span
                  key={cap}
                  className="inline-block rounded bg-[#F4F2ED] px-1.5 py-0.5 text-hb-xs font-medium text-[#434B59] truncate max-w-full"
                >
                  {cap}
                </span>
              ))}
            </div>
          ) : (
            <p className="mt-1.5 truncate text-hb-xs font-medium text-[#646E7E]">
              {specSummaryText}
            </p>
          )}
        </div>

        {/* 하단: 가격 강조 + 견적함 액션 */}
        <div className="mt-3 pt-2.5 border-t border-[#ECE9E2] flex items-center justify-between gap-2 min-w-0">
          <div className="min-w-0 flex-1">
            {sold ? (
              <span className="text-hb-sm font-bold text-[#646E7E] truncate block">
                판매완료 · 유사재고 문의
              </span>
            ) : priced ? (
              <strong className="block text-hb-base sm:text-hb-lg font-extrabold tracking-tight text-[#0E1A2B] tabular-nums truncate">
                {priceText}
              </strong>
            ) : (
              <strong className="block text-hb-sm sm:text-hb-base font-extrabold text-[#0E1A2B] truncate">
                {priceText}
              </strong>
            )}
          </div>

          {!isSelectMode && !sold ? (
            <button
              type="button"
              onClick={handleToggleBasket}
              aria-pressed={inBasket}
              title={inBasket ? "견적함에서 제외" : "관심 매물 견적함에 담기"}
              aria-label={`${product.title} ${
                inBasket ? "견적함에서 제외" : "견적함에 담기"
              }`}
              className={`shrink-0 inline-flex items-center gap-1 rounded-lg px-2.5 py-1 text-hb-xs font-bold transition-all duration-150 active:scale-[0.98] cursor-pointer ${
                inBasket
                  ? "bg-[#0E1A2B] text-white"
                  : "bg-[#F4F3EF] text-[#0E1A2B] hover:bg-[#0E1A2B] hover:text-white"
              }`}
            >
              <Icon
                d={inBasket ? ICON.check : ICON.plus}
                className={`h-3 w-3 ${
                  inBasket ? "text-[#FF8A50]" : "currentColor"
                }`}
              />
              <span>{inBasket ? "담김" : "견적함"}</span>
            </button>
          ) : (
            <span className="inline-flex shrink-0 items-center gap-0.5 text-hb-xs font-semibold text-[#646E7E] group-hover:text-[#0E1A2B] transition-colors">
              <span>보기</span>
              <Icon d={ICON.right} className="h-3.5 w-3.5" />
            </span>
          )}
        </div>
      </div>
    </article>
  );

  if (onSelect) {
    return (
      <div
        role="button"
        tabIndex={0}
        aria-label={`${product.title} ${isSelectMode ? "선택" : "상세 보기"}`}
        onClick={() => onSelect(product)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onSelect(product);
          }
        }}
        className="block h-full w-full min-w-0 cursor-pointer text-left rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0E1A2B]"
      >
        {cardInner}
      </div>
    );
  }

  return (
    <Link
      href={`/${product.id}`}
      className="block h-full min-w-0 rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0E1A2B]"
    >
      {cardInner}
    </Link>
  );
}


// 파일 경로: components/products/product-compare-modal.tsx
"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import {
  clearRecentViewedProducts,
  extractModelName,
  extractSpecCapsules,
  formatProductPrice,
  getProductStatusLabel,
  getRecentViewedProducts,
  isProductSold,
  normalizeProductCategory,
  parseProductDescription,
  RECENT_VIEWED_EVENT,
  removeRecentViewedProduct,
  type QuoteBasketItem,
  type RecentViewedItem,
  updateQuoteBasketItemQuantity,
  removeQuoteBasketItem,
} from "../../lib/site";
import { Icon, ICON, Modal, SafeImg } from "../../lib/ui";
import { V2SpatialFitPlanner } from "./v2-spatial-fit-planner";

function extractWidthMmFromItem(item: QuoteBasketItem): number | null {
  const text = `${item.title || ""}\n${item.description || ""}`;
  // 1) 명시적 가로/폭 mm 패턴 또는 가로×세로×높이 첫 숫자 추출
  const dimMatch = text.match(
    /(?:가로|폭)\s*[:：]?\s*(\d{3,4})\s*mm|\b(\d{3,4})\s*[x×*]\s*\d{3,4}/i
  );
  if (dimMatch) {
    const val = Number(dimMatch[1] || dimMatch[2]);
    if (val >= 350 && val <= 3000) return val;
  }
  // 2) 업소용 표준 박스 규격 참고치
  if (/45\s*박스/.test(text)) return 1260;
  if (/25\s*박스|30\s*박스/.test(text)) return 650;
  return null;
}

export function ProductCompareModal({
  open,
  onClose,
  items,
}: {
  open: boolean;
  onClose: () => void;
  items: QuoteBasketItem[];
}) {
  const compareItems = items.slice(0, 3);

  // 각 상품의 description에서 파싱된 실제 사양(specs) 추출
  const parsedSpecsPerItem = compareItems.map((item) => {
    const parsed = parseProductDescription(item.description);
    const map = new Map<string, string>();
    for (const s of parsed.specs) {
      if (s.label && s.value) {
        map.set(s.label.trim(), s.value.trim());
      }
    }
    return map;
  });

  // 실제 데이터에 존재하는 사양 라벨만 수집 (최대 6개 핵심 항목)
  const allSpecLabels = Array.from(
    new Set(
      parsedSpecsPerItem.flatMap((map) =>
        Array.from(map.keys()).filter((k) => k !== "모델명")
      )
    )
  ).slice(0, 6);

  const getWarrantyText = (catRaw: string) => {
    const cat = normalizeProductCategory(catRaw);
    if (cat === "에어컨/냉난방기") return "계약조건별 최대 8개월";
    if (cat === "냉장고" || cat === "세탁기/건조기")
      return "계약조건별 최대 4개월";
    return "품목·계약조건별 협의";
  };

  return (
    <Modal
      open={open}
      onClose={onClose}
      label="관심 매물 상세 비교"
      panelClassName="max-w-4xl"
    >
      <div className="flex max-h-[90vh] w-full flex-col overflow-hidden rounded-xl border border-[#E5E2DC] bg-white shadow-2xl">
        {/* 상단 헤더 */}
        <div className="flex items-center justify-between border-b border-[#E5E2DC] bg-[#0E1A2B] px-5 py-4 text-white">
          <div>
            <span className="text-hb-xs font-bold text-[#FF8A50]">
              실매물 스펙 · 조건 한눈에 비교
            </span>
            <h2 className="text-hb-lg font-extrabold">
              선택한 매물 비교 ({compareItems.length}건)
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="비교 창 닫기"
            className="grid h-8 w-8 place-items-center rounded-lg bg-white/10 text-white hover:bg-white/20"
          >
            <Icon d={ICON.close} className="w-5 h-5" />
          </button>
        </div>

        {/* 비교 테이블 본문 */}
        <div className="flex-1 overflow-x-auto overflow-y-auto p-4 sm:p-6">
          {compareItems.length === 0 ? (
            <div className="py-12 text-center text-hb-sm text-[#646E7E]">
              비교할 상품이 없습니다. 갤러리에서 관심 매물을 견적함에 담아주세요.
            </div>
          ) : (
            <>
              {(() => {
                const widths = compareItems
                  .map((it) => {
                    const w = extractWidthMmFromItem(it);
                    const qty = it.quantity && it.quantity > 0 ? it.quantity : 1;
                    return w ? { title: it.title, width: w * qty, qty } : null;
                  })
                  .filter(
                    (x): x is { title: string; width: number; qty: number } =>
                      Boolean(x)
                  );

                if (widths.length === 0) return null;
                const totalWidthMm = widths.reduce(
                  (acc, cur) => acc + cur.width,
                  0
                );

                return (
                  <div className="mb-4 space-y-3">
                    <div className="rounded-lg border border-[#FADCD0] bg-[#FFF5F0] px-4 py-2.5 text-hb-xs sm:text-hb-sm text-[#3E4756] flex flex-wrap items-center justify-between gap-2">
                      <span>
                        <strong className="text-[#0E1A2B]">
                          설치 공간 가로폭 참고:
                        </strong>{" "}
                        치수가 확인된 {widths.length}종 매물의 가로폭 합계는 약{" "}
                        <strong className="text-[#D9531E] font-extrabold tabular-nums">
                          {totalWidthMm.toLocaleString()}mm (
                          {(totalWidthMm / 1000).toFixed(2)}m)
                        </strong>
                        입니다.
                      </span>
                      <span className="text-hb-xs text-[#646E7E]">
                        ※ 방열 및 문열림을 위해 양옆 최소 100mm 이상 여유 공간을
                        권장합니다.
                      </span>
                    </div>
                    <V2SpatialFitPlanner
                      overrideWidthMm={totalWidthMm}
                      title={compareItems.map((it) => it.title).join(" + ")}
                    />
                  </div>
                );
              })()}

              <table className="w-full min-w-[540px] border-collapse text-left text-hb-sm">
                <thead>
                  <tr className="border-b border-[#E5E2DC]">
                    <th className="w-[110px] sm:w-[130px] bg-[#FAF9F7] p-3 font-bold text-[#646E7E] align-middle">
                      비교 항목
                    </th>
                    {compareItems.map((item) => {
                      const sold = isProductSold(item.status);
                      return (
                        <th
                          key={item.id}
                          className="w-1/3 p-3 align-top border-l border-[#E5E2DC]"
                        >
                          <div className="flex flex-col gap-2">
                            <div className="relative aspect-[4/3] w-full overflow-hidden rounded-lg border border-[#E5E2DC] bg-[#F7F6F3]">
                              <SafeImg
                                src={item.imageUrl}
                                alt={item.title}
                                className="h-full w-full object-cover"
                              />
                              {sold && (
                                <span className="absolute inset-0 flex items-center justify-center bg-[#0E1A2B]/55 text-hb-xs font-bold text-white">
                                  판매완료
                                </span>
                              )}
                            </div>
                            <Link
                              href={`/${item.id}`}
                              onClick={onClose}
                              className="font-bold text-[#0E1A2B] hover:text-[#D9531E] line-clamp-2 leading-snug"
                            >
                              {item.title}
                            </Link>
                            <div className="flex items-center justify-between gap-1 pt-1">
                              <Link
                                href={`/${item.id}`}
                                onClick={onClose}
                                className="text-hb-xs font-semibold text-[#646E7E] underline"
                              >
                                상세보기
                              </Link>
                              <button
                                type="button"
                                onClick={() => removeQuoteBasketItem(item.id)}
                                className="text-hb-xs font-semibold text-red-600 hover:underline"
                              >
                                제외
                              </button>
                            </div>
                          </div>
                        </th>
                      );
                    })}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E5E2DC]">
                  {/* 1. 판매 가격 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      판매 가격
                    </th>
                    {compareItems.map((item) => {
                      const sold = isProductSold(item.status);
                      return (
                        <td
                          key={item.id}
                          className="p-3 font-extrabold text-hb-base text-[#D9531E] border-l border-[#E5E2DC] tabular-nums"
                        >
                          {sold
                            ? "판매완료 (유사재고 문의)"
                            : formatProductPrice(item.price, item.category)}
                        </td>
                      );
                    })}
                  </tr>

                  {/* 2. 희망 수량 조절 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      문의 수량
                    </th>
                    {compareItems.map((item) => {
                      const qty = item.quantity || 1;
                      return (
                        <td
                          key={item.id}
                          className="p-3 border-l border-[#E5E2DC]"
                        >
                          <div className="inline-flex items-center rounded border border-[#CFCAC0] bg-white">
                            <button
                              type="button"
                              onClick={() =>
                                updateQuoteBasketItemQuantity(item.id, qty - 1)
                              }
                              aria-label="수량 감소"
                              className="h-7 w-7 font-bold text-[#0E1A2B] hover:bg-[#FAF9F7]"
                            >
                              -
                            </button>
                            <span className="px-2.5 text-hb-xs font-bold tabular-nums">
                              {qty}대
                            </span>
                            <button
                              type="button"
                              onClick={() =>
                                updateQuoteBasketItemQuantity(item.id, qty + 1)
                              }
                              aria-label="수량 증가"
                              className="h-7 w-7 font-bold text-[#0E1A2B] hover:bg-[#FAF9F7]"
                            >
                              +
                            </button>
                          </div>
                        </td>
                      );
                    })}
                  </tr>

                  {/* 3. 품목 분류 및 판매 상태 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      품목 / 상태
                    </th>
                    {compareItems.map((item) => (
                      <td key={item.id} className="p-3 border-l border-[#E5E2DC]">
                        <span className="font-semibold text-[#0E1A2B]">
                          {normalizeProductCategory(item.category)}
                        </span>
                        <span className="ml-1.5 inline-block rounded bg-[#FAF9F7] border border-[#E5E2DC] px-1.5 py-0.5 text-hb-xs font-bold text-[#3E4756]">
                          {getProductStatusLabel(item.status)}
                        </span>
                      </td>
                    ))}
                  </tr>

                  {/* 4. 확인된 모델명 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      모델명
                    </th>
                    {compareItems.map((item) => {
                      const model =
                        item.modelName ||
                        extractModelName(item.description, item.title);
                      return (
                        <td
                          key={item.id}
                          className="p-3 font-mono text-hb-xs border-l border-[#E5E2DC]"
                        >
                          {model ? (
                            <span className="font-bold text-[#0E1A2B]">
                              {model}
                            </span>
                          ) : (
                            <span className="text-[#858076]">
                              정보 없음 (상세 문의)
                            </span>
                          )}
                        </td>
                      );
                    })}
                  </tr>

                  {/* 5. 확인된 상태 등급 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      상태 등급
                    </th>
                    {compareItems.map((item) => (
                      <td key={item.id} className="p-3 border-l border-[#E5E2DC]">
                        {item.conditionGrade ? (
                          <span className="inline-block rounded bg-[#FFF5F0] border border-[#FADCD0] px-2 py-0.5 text-hb-xs font-bold text-[#D9531E]">
                            {item.conditionGrade}
                          </span>
                        ) : (
                          <span className="text-[#646E7E]">
                            세척·점검 완료 (상세 문의)
                          </span>
                        )}
                      </td>
                    ))}
                  </tr>

                  {/* 6. 핵심 규격 캡슐 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      주요 규격
                    </th>
                    {compareItems.map((item) => {
                      const tags = extractSpecCapsules(
                        item.title,
                        item.description,
                        4
                      );
                      return (
                        <td
                          key={item.id}
                          className="p-3 border-l border-[#E5E2DC]"
                        >
                          {tags.length > 0 ? (
                            <div className="flex flex-wrap gap-1">
                              {tags.map((t) => (
                                <span
                                  key={t}
                                  className="rounded bg-[#FAF9F7] border border-[#E5E2DC] px-2 py-0.5 text-hb-xs font-semibold text-[#0E1A2B]"
                                >
                                  {t}
                                </span>
                              ))}
                            </div>
                          ) : (
                            <span className="text-[#858076]">
                              정보 없음 (상세 문의)
                            </span>
                          )}
                        </td>
                      );
                    })}
                  </tr>

                  {/* 7. 실제 상세 설명에서 파싱된 세부 사양 행 */}
                  {allSpecLabels.map((label) => (
                    <tr key={label}>
                      <th className="bg-[#FAF9F7] p-3 font-semibold text-[#3E4756]">
                        {label}
                      </th>
                      {compareItems.map((item, idx) => {
                        const val = parsedSpecsPerItem[idx]?.get(label);
                        return (
                          <td
                            key={item.id + label}
                            className="p-3 border-l border-[#E5E2DC] text-[#0E1A2B]"
                          >
                            {val || (
                              <span className="text-[#858076]">
                                정보 없음 (상세 문의)
                              </span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}

                  {/* 8. 보증 및 증빙 기준 */}
                  <tr>
                    <th className="bg-[#FAF9F7] p-3 font-bold text-[#0E1A2B]">
                      보증 / 증빙
                    </th>
                    {compareItems.map((item) => (
                      <td
                        key={item.id}
                        className="p-3 border-l border-[#E5E2DC] text-hb-xs text-[#3E4756]"
                      >
                        <span className="block font-semibold text-[#0E1A2B]">
                          {getWarrantyText(item.category)}
                        </span>
                        <span className="text-hb-xs text-[#646E7E]">
                          세금계산서 · 카드 · 직배송 상담
                        </span>
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </>
          )}
        </div>

        {/* 하단 액션 바 */}
        <div className="flex flex-wrap items-center justify-between gap-3 border-t border-[#E5E2DC] bg-[#FAF9F7] px-5 py-3.5">
          <p className="text-hb-xs text-[#646E7E]">
            ※ 표기된 사양 외에 설치 공간·전원·배관 호환 여부는 묶음 문의로 남겨주시면 정확히 안내해 드립니다.
          </p>
          <div className="flex items-center gap-2 ml-auto">
            <button
              type="button"
              onClick={onClose}
              className="hb-btn-outline h-10 px-4 text-hb-sm"
            >
              닫기
            </button>
            <Link
              href="/inquiry?write=1&bundle=1"
              onClick={onClose}
              className="hb-btn-accent h-10 px-5 text-hb-sm"
            >
              <span>이 구성으로 일괄 견적 문의</span>
              <Icon d={ICON.arrow} className="w-3.5 h-3.5" />
            </Link>
          </div>
        </div>
      </div>
    </Modal>
  );
}

/**
 * [신규 기능 ④] 비로그인 최근 본 매물 가로 스트립 컴포넌트
 * - /gallery 및 /[id] 하단에 배치되어 최근 조회한 매물로 즉시 복귀할 수 있습니다.
 */
export function RecentViewedStrip({
  excludeId,
  className = "",
}: {
  excludeId?: string;
  className?: string;
}) {
  const [items, setItems] = useState<RecentViewedItem[]>([]);

  useEffect(() => {
    const sync = () => {
      const all = getRecentViewedProducts();
      setItems(excludeId ? all.filter((x) => x.id !== excludeId) : all);
    };
    sync();
    window.addEventListener(RECENT_VIEWED_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(RECENT_VIEWED_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [excludeId]);

  if (items.length === 0) return null;

  return (
    <section
      aria-label="최근 본 매물"
      className={`rounded-xl border border-[#E5E2DC] bg-white p-4 sm:p-5 shadow-2xs ${className}`}
    >
      <div className="flex items-center justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <span className="h-2 w-2 rounded-full bg-[#D9531E]" />
          <h2 className="text-hb-base font-extrabold text-[#0E1A2B]">
            최근 본 매물 ({items.length})
          </h2>
          <span className="hidden sm:inline text-hb-xs text-[#646E7E]">
            로그인 없이 현재 기기에만 안전하게 저장됩니다
          </span>
        </div>
        <button
          type="button"
          onClick={() => clearRecentViewedProducts()}
          className="text-hb-xs font-semibold text-[#646E7E] hover:text-[#0E1A2B] underline underline-offset-2"
        >
          기록 비우기
        </button>
      </div>

      <div className="flex gap-3 overflow-x-auto pb-1 scrollbar-none">
        {items.map((item) => {
          const sold = isProductSold(item.status);
          return (
            <div
              key={item.id}
              className="group relative flex w-[170px] sm:w-[190px] shrink-0 flex-col overflow-hidden rounded-lg border border-[#E5E2DC] bg-[#FAF9F7] hover:border-[#0E1A2B] transition-colors"
            >
              <button
                type="button"
                onClick={(e) => {
                  e.preventDefault();
                  removeRecentViewedProduct(item.id);
                }}
                aria-label={`${item.title} 최근 본 목록에서 삭제`}
                className="absolute right-1.5 top-1.5 z-10 grid h-5 w-5 place-items-center rounded-full bg-black/60 text-white hover:bg-red-600"
              >
                <Icon d={ICON.close} className="w-3 h-3" />
              </button>

              <Link href={`/${item.id}`} className="flex flex-1 flex-col">
                <div className="relative aspect-[4/3] w-full overflow-hidden bg-[#F7F6F3] border-b border-[#E5E2DC]">
                  <SafeImg
                    src={item.imageUrl}
                    alt={item.title}
                    className={`h-full w-full object-cover ${
                      sold ? "grayscale opacity-70" : ""
                    }`}
                  />
                  {sold && (
                    <span className="absolute bottom-1.5 left-1.5 rounded bg-[#0E1A2B]/85 px-1.5 py-0.5 text-hb-xs font-bold text-white">
                      판매완료
                    </span>
                  )}
                </div>
                <div className="p-2.5 flex flex-1 flex-col justify-between">
                  <div>
                    <span className="block text-hb-xs font-semibold text-[#646E7E] truncate">
                      {item.category}
                    </span>
                    <p className="mt-0.5 line-clamp-1 text-hb-xs font-bold text-[#0E1A2B] group-hover:text-[#D9531E]">
                      {item.title}
                    </p>
                  </div>
                  <strong className="mt-1.5 block text-hb-sm font-extrabold text-[#0E1A2B] tabular-nums">
                    {sold
                      ? "판매완료"
                      : formatProductPrice(item.price, item.category)}
                  </strong>
                </div>
              </Link>
            </div>
          );
        })}
      </div>
    </section>
  );
}


// 파일 경로: components/products/product-detail-gallery.tsx
"use client";

import React, { useState, useCallback, useEffect } from "react";
import Link from "next/link";
import toast from "react-hot-toast";
import { Icon, ICON, SafeImg } from "../../lib/ui";
import { ProductStatusBadge } from "./product-status-badge";
import { getAdminAuthHeaders, isAuthorizedAdminUser, supabase } from "../../lib/supabase";
import {
  addRecentViewedProduct,
  generatePromoPostText,
  getQuoteBasket,
  isProductSold,
  QUOTE_BASKET_EVENT,
  smsHref,
  STORE,
  telHref,
  toggleQuoteBasketItem,
  trackEvent,
  type QuoteBasketItem,
} from "../../lib/site";

export function ProductDetailGallery({
  id,
  title,
  category,
  price,
  modelName,
  conditionGrade,
  images,
  status,
  createdAt,
}: {
  id?: string;
  title: string;
  category?: string;
  price?: number | null;
  modelName?: string | null;
  conditionGrade?: string | null;
  images: string[];
  status: string | null;
  createdAt?: string | null;
}) {
  const displayImages = images.length > 0 ? images : [""];
  const [idx, setIdx] = useState(0);
  const [isZoomOpen, setIsZoomOpen] = useState(false);
  const sold = isProductSold(status);

  useEffect(() => {
    if (!id) return;
    addRecentViewedProduct({
      id,
      title,
      category: category || "기타",
      price: price ?? null,
      status,
      conditionGrade: conditionGrade ?? null,
      modelName: modelName ?? null,
      imageUrl: images[0] || null,
    });

    // 상세 페이지 직접 유입 및 조회수 집계 (sessionStorage "viewed_products" JSON 배열 기준 1회 집계)
    if (typeof window !== "undefined") {
      try {
        const raw = sessionStorage.getItem("viewed_products");
        const list: string[] = raw ? JSON.parse(raw) : [];
        if (!list.includes(String(id))) {
          getAdminAuthHeaders().then((authHeaders) => {
            fetch(`/api/products/${id}/view`, {
              method: "POST",
              headers: authHeaders,
            })
              .then((res) => {
                if (res.ok) {
                  try {
                    const currentRaw = sessionStorage.getItem("viewed_products");
                    const currentList: string[] = currentRaw
                      ? JSON.parse(currentRaw)
                      : [];
                    if (!currentList.includes(String(id))) {
                      currentList.push(String(id));
                      sessionStorage.setItem(
                        "viewed_products",
                        JSON.stringify(currentList)
                      );
                    }
                  } catch {}
                }
              })
              .catch(() => {
                // 조회수 집계 비동기 실패는 조용히 무시
              });
          });
        }
      } catch {}
    }
  }, [id, title, category, price, status, conditionGrade, modelName, images]);

  const go = useCallback(
    (d: number) => {
      if (displayImages.length < 2) return;
      setIdx((i) => (i + d + displayImages.length) % displayImages.length);
    },
    [displayImages.length]
  );

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isZoomOpen) {
        setIsZoomOpen(false);
        return;
      }
      if (displayImages.length < 2) return;
      if (e.key === "ArrowLeft") go(-1);
      if (e.key === "ArrowRight") go(1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [displayImages.length, go, isZoomOpen]);

  return (
    <>
      <div className="flex flex-col rounded-xl overflow-hidden border border-[#E5E2DC] bg-white shadow-card">
        {/* 상단 쇼룸 이미지 뷰어 바 */}
        <div className="bg-[#0E1A2B] text-white px-4 py-2.5 flex items-center justify-between gap-2 text-hb-xs">
          <div className="flex items-center gap-2">
            <span className="inline-block w-2 h-2 rounded-full bg-[#D9531E]" />
            <span className="font-bold tracking-wider uppercase text-white/90">
              SHOWROOM STUDIO PHOTO
            </span>
          </div>
          <span className="text-white/75 font-medium tabular-nums">
            실물 촬영 사진 ({idx + 1} / {displayImages.length})
          </span>
        </div>

        {/* 메인 프리뷰 영역: 시원시원한 대형 뷰 (스튜디오 백드롭 적용) */}
        <div
          onClick={() => displayImages[0] && setIsZoomOpen(true)}
          className="relative w-full aspect-[4/3] sm:aspect-[16/11] hb-studio-backdrop flex items-center justify-center p-1 sm:p-2 overflow-hidden cursor-zoom-in group select-none"
          title="클릭하여 원본 비율 전체화면으로 확대"
        >
          <SafeImg
            key={displayImages[idx]}
            src={displayImages[idx]}
            alt={`${title} - 사진 ${idx + 1}`}
            eager
            className={`w-full h-full object-contain transition-transform duration-300 group-hover:scale-[1.02] ${
              sold ? "grayscale opacity-75" : ""
            }`}
          />

          <div className="absolute top-3.5 left-3.5 z-10">
            <ProductStatusBadge status={status} createdAt={createdAt} />
          </div>

          {sold && (
            <div className="absolute inset-0 flex items-center justify-center bg-[#0E1A2B]/45">
              <span className="px-5 py-2 rounded bg-[#0E1A2B]/90 text-white text-hb-sm font-bold tracking-[0.2em] border border-white/20">
                판매완료
              </span>
            </div>
          )}

          {displayImages[0] && (
            <div className="absolute top-3.5 right-3.5 bg-[#0E1A2B]/75 text-white text-hb-xs font-semibold px-3 py-1 rounded-md flex items-center gap-1.5 pointer-events-none">
              <Icon d={ICON.search} className="w-3.5 h-3.5" />
              <span>원본 확대</span>
            </div>
          )}

          {displayImages.length > 1 && (
            <>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  go(-1);
                }}
                aria-label="이전 사진"
                className="absolute left-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/95 text-[#0E1A2B] shadow-md flex items-center justify-center hover:bg-white transition-colors z-10"
              >
                <Icon d={ICON.left} className="w-5 h-5" />
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  go(1);
                }}
                aria-label="다음 사진"
                className="absolute right-3 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/95 text-[#0E1A2B] shadow-md flex items-center justify-center hover:bg-white transition-colors z-10"
              >
                <Icon d={ICON.right} className="w-5 h-5" />
              </button>
            </>
          )}
        </div>

        {/* 썸네일 스트립 */}
        {displayImages.length > 1 && (
          <div className="flex gap-2.5 p-3 sm:px-5 bg-white border-t border-[#E5E2DC] overflow-x-auto">
            {displayImages.map((img, i) => (
              <button
                key={img + i}
                type="button"
                onClick={() => setIdx(i)}
                aria-label={`${i + 1}번 사진 선택`}
                className={`relative w-16 h-16 shrink-0 rounded-lg overflow-hidden bg-[#F5F4F0] border transition-all ${
                  i === idx
                    ? "border-[#D9531E] ring-2 ring-[#D9531E]/35"
                    : "border-[#E5E2DC] opacity-65 hover:opacity-100"
                }`}
              >
                <SafeImg
                  src={img}
                  alt=""
                  className="w-full h-full object-cover"
                />
              </button>
            ))}
          </div>
        )}
      </div>

      {/* 전체화면 확대 라이트박스 */}
      {isZoomOpen && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label="상품 사진 전체화면 확대"
          onClick={() => setIsZoomOpen(false)}
          className="fixed inset-0 z-[90] bg-black/95 flex flex-col items-center justify-center p-4 select-none"
        >
          <div className="absolute top-4 left-4 right-4 flex items-center justify-between text-white z-20">
            <span className="text-hb-sm font-semibold bg-white/15 px-3.5 py-1 rounded-full tabular-nums">
              {idx + 1} / {displayImages.length}
            </span>
            <button
              type="button"
              onClick={() => setIsZoomOpen(false)}
              aria-label="확대 창 닫기"
              className="w-10 h-10 rounded-full bg-white/15 hover:bg-white/30 flex items-center justify-center text-white"
            >
              <Icon d={ICON.close} className="w-6 h-6" />
            </button>
          </div>

          <div
            onClick={(e) => e.stopPropagation()}
            className="relative max-w-full max-h-[82vh] flex items-center justify-center"
          >
            <SafeImg
              src={displayImages[idx]}
              alt={title}
              eager
              className="max-w-full max-h-[82vh] w-auto h-auto object-contain rounded"
            />
          </div>

          {displayImages.length > 1 && (
            <>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  go(-1);
                }}
                aria-label="이전 사진"
                className="absolute left-4 top-1/2 -translate-y-1/2 w-11 h-11 rounded-full bg-white/20 hover:bg-white/35 text-white flex items-center justify-center z-20"
              >
                <Icon d={ICON.left} className="w-6 h-6" />
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  go(1);
                }}
                aria-label="다음 사진"
                className="absolute right-4 top-1/2 -translate-y-1/2 w-11 h-11 rounded-full bg-white/20 hover:bg-white/35 text-white flex items-center justify-center z-20"
              >
                <Icon d={ICON.right} className="w-6 h-6" />
              </button>
            </>
          )}
        </div>
      )}
    </>
  );
}

/**
 * 상품 상세 링크 복사 버튼 (카톡/문자 공유용)
 */
export function CopyProductLinkButton({
  productTitle,
}: {
  productTitle: string;
}) {
  const handleCopy = async () => {
    try {
      const shareUrl = window.location.href;
      await navigator.clipboard.writeText(shareUrl);
      toast.success("상품 페이지 주소가 복사되었습니다.");
    } catch {
      toast.error("주소 복사에 실패했습니다.");
    }
  };

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="inline-flex items-center gap-1.5 rounded-lg border border-[#D8D3C8] bg-white px-3 py-1.5 text-hb-xs font-bold text-[#3E4856] hover:border-[#0E1A2B] hover:text-[#0E1A2B] transition-colors shadow-2xs"
      title={`${productTitle} 링크 복사`}
    >
      <Icon d={ICON.copy} className="w-3.5 h-3.5 text-[#D9531E]" />
      <span>상품 링크 복사</span>
    </button>
  );
}

/**
 * [신규 기능] 상품 상세 페이지에서 견적함에 담기/빼기 토글 버튼
 */
export function QuoteBasketButton({
  item,
  className = "",
}: {
  item: QuoteBasketItem;
  className?: string;
}) {
  const [inBasket, setInBasket] = useState(false);

  useEffect(() => {
    const sync = () => {
      setInBasket(getQuoteBasket().some((x) => x.id === item.id));
    };
    sync();
    window.addEventListener(QUOTE_BASKET_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(QUOTE_BASKET_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [item.id]);

  const handleToggle = () => {
    const res = toggleQuoteBasketItem(item);
    if (res.limitReached) {
      toast.error("견적함에는 최대 8개까지 담을 수 있습니다.");
      return;
    }
    if (res.added) {
      trackEvent("add_to_quote_basket", {
        category: item.category,
        location: "detail",
      });
      toast.success("관심 매물 견적함에 담았습니다.");
    } else {
      toast("견적함에서 제외했습니다.");
    }
  };

  return (
    <button
      type="button"
      onClick={handleToggle}
      aria-pressed={inBasket}
      className={
        className ||
        `inline-flex items-center justify-center gap-1.5 rounded-lg border px-4 h-10 text-hb-xs sm:text-hb-sm font-bold transition-colors w-full ${
          inBasket
            ? "border-[#D9531E] bg-[#FFF5F0] text-[#D9531E]"
            : "border-[#CFCAC0] bg-[#FAF9F7] text-[#0E1A2B] hover:border-[#0E1A2B]"
        }`
      }
    >
      <Icon
        d={inBasket ? ICON.check : ICON.plus}
        className={`w-4 h-4 ${
          inBasket ? "text-[#D9531E]" : "text-[#0E1A2B]"
        }`}
      />
      <span>
        {inBasket
          ? "관심 매물 견적함에 담김 (클릭 시 제외)"
          : "관심 매물 견적함에 담기 (복수 비교·묶음 문의)"}
      </span>
    </button>
  );
}

/**
 * [신규 기능] 네이버 블로그 / 당근마켓 / 중고나라 홍보글 원클릭 복사 버튼
 */
export function CopyPromoPostButton({
  product,
  className = "",
}: {
  product: {
    id: string;
    title: string;
    category?: string | null;
    price?: number | null;
    status?: string | null;
    condition_grade?: string | null;
    description?: string | null;
  };
  className?: string;
}) {
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    supabase.auth
      .getSession()
      .then(({ data }) =>
        setIsAdmin(isAuthorizedAdminUser(data.session?.user))
      );
    const { data: sub } = supabase.auth.onAuthStateChange((_e, session) =>
      setIsAdmin(isAuthorizedAdminUser(session?.user))
    );
    return () => sub.subscription.unsubscribe();
  }, []);

  if (!isAdmin) return null;

  const handleCopyPromo = async () => {
    try {
      const text = generatePromoPostText(product);
      await navigator.clipboard.writeText(text);
      toast.success(
        "블로그·당근마켓용 홍보글 양식이 복사되었습니다. 그대로 붙여넣기(Ctrl+V) 하세요!"
      );
    } catch {
      toast.error("홍보글 복사에 실패했습니다.");
    }
  };

  return (
    <div className="inline-flex items-center gap-1.5">
      <Link
        href={`/admin?search=${encodeURIComponent(product.id)}`}
        className="inline-flex items-center gap-1.5 rounded-lg border border-[#D8D3C8] bg-[#FAF9F7] px-3 py-1.5 text-hb-xs font-bold text-[#0E1A2B] hover:border-[#0E1A2B] hover:bg-white transition-colors shadow-2xs"
        title="관리자 페이지에서 이 상품 정보 수정하기"
      >
        <Icon d={ICON.pen} className="w-3.5 h-3.5 text-[#0E1A2B]" />
        <span>상품 수정 (관리자)</span>
      </Link>
      <button
        type="button"
        onClick={handleCopyPromo}
        className={
          className ||
          "inline-flex items-center gap-1.5 rounded-lg border border-[#D8D3C8] bg-[#FAF9F7] px-3 py-1.5 text-hb-xs font-bold text-[#0E1A2B] hover:border-[#0E1A2B] hover:bg-white transition-colors shadow-2xs"
        }
        title="네이버 블로그·당근마켓·카페 게시글 양식으로 상품 요약 복사 (관리자 전용)"
      >
        <Icon d={ICON.copy} className="w-3.5 h-3.5 text-[#D9531E]" />
        <span>홍보글 양식 복사 (관리자)</span>
      </button>
    </div>
  );
}

/**
 * [인터랙티브 시너지 컴포넌트]
 * 상품 상세 우측의 설치 환경 체크리스트를 고객이 직접 클릭해 선택하면,
 * 온라인 문의 / 문자(SMS) / 견적함에 해당 현장 조건이 자동으로 첨부됩니다.
 */
const QUICK_ENV_CHIPS_BY_CATEGORY: Record<string, readonly string[]> = {
  업소용기기: [
    "단상 220V",
    "삼상 380V",
    "1층 매장",
    "계단·턱 있음",
    "기존 설비 철거·매입 희망",
    "세금계산서 발행 요청",
  ],
  "에어컨/냉난방기": [
    "단상 220V",
    "삼상 380V",
    "실외기 1층/베란다",
    "외벽 앵글 필요",
    "배관 5m 이내",
    "배관 10m 이상",
  ],
  default: [
    "엘리베이터 있음",
    "계단 운반(2층 이상)",
    "기존 가전 보상매입/수거 희망",
    "문폭 80cm 이상 여유",
  ],
};

export function InteractiveChecklistAndCta({
  product,
  categoryLabel,
  sold,
  modelName,
  firstImageUrl,
  checklistConfig,
}: {
  product: {
    id: string;
    title: string;
    price: number | null;
    status: string | null;
    condition_grade?: string | null;
    description?: string | null;
  };
  categoryLabel: string;
  sold: boolean;
  modelName: string | null;
  firstImageUrl: string | null;
  checklistConfig: {
    badge: string;
    title: string;
    isB2B: boolean;
    rows: ReadonlyArray<{ label: string; desc: string }>;
  };
}) {
  const [selectedChips, setSelectedChips] = useState<string[]>([]);
  const chips =
    QUICK_ENV_CHIPS_BY_CATEGORY[categoryLabel] ||
    QUICK_ENV_CHIPS_BY_CATEGORY.default;

  const toggleChip = (chip: string) => {
    setSelectedChips((prev) =>
      prev.includes(chip) ? prev.filter((c) => c !== chip) : [...prev, chip]
    );
  };

  const envSummary =
    selectedChips.length > 0 ? selectedChips.join(", ") : "";

  const inquiryParams = new URLSearchParams({
    write: "1",
    type: categoryLabel === "업소용기기" ? "대량·업소용 상담" : "구매 문의",
    productId: String(product.id),
    title: sold
      ? `[유사매물 재고문의] [${categoryLabel}] ${product.title}`
      : `[상품문의] [${categoryLabel}] ${product.title}`,
    category: categoryLabel,
  });
  if (modelName) {
    inquiryParams.set("model", modelName);
  }
  if (envSummary) {
    inquiryParams.set("envNote", envSummary);
  }
  const inquiryHref = `/inquiry?${inquiryParams.toString()}`;

  const smsBody = sold
    ? `[한밭중고전자 유사매물문의] 판매완료된 '${product.title}'${
        modelName ? ` (${modelName})` : ""
      }${
        envSummary ? ` / 현장조건: ${envSummary}` : ""
      }와 비슷한 스펙의 현재 구매 가능한 재고가 있는지 문의드립니다.`
    : `[한밭중고전자 상품문의] [${categoryLabel}] ${product.title}${
        modelName ? ` (${modelName})` : ""
      }${
        envSummary ? ` / 현장조건: ${envSummary}` : ""
      } 재고 및 배송·설치 견적 문의드립니다.`;

  return (
    <div className="mt-4 pt-4 border-t border-[#E5E2DC] space-y-4">
      {/* 1. 인터랙티브 설치 환경 체크 및 터치 칩 */}
      <div>
        <div className="flex flex-wrap items-center justify-between gap-2 mb-2">
          <strong className="font-bold text-[#0E1A2B] text-hb-xs sm:text-hb-sm flex items-center gap-1.5">
            <Icon d={ICON.check} className="w-4 h-4 text-[#D9531E]" />
            <span>{checklistConfig.title}</span>
          </strong>
          <span
            className={`rounded px-2 py-0.5 text-hb-xs font-bold ${
              checklistConfig.isB2B
                ? "bg-[#0E1A2B] text-white"
                : "bg-[#D9531E]/10 text-[#D9531E]"
            }`}
          >
            {checklistConfig.badge}
          </span>
        </div>

        <dl className="grid grid-cols-1 gap-1 text-hb-xs bg-[#FAF9F7] border-l-2 border-[#0E1A2B] pl-3 py-2">
          {checklistConfig.rows.map((row) => (
            <div key={row.label} className="flex items-start gap-2">
              <dt className="w-[74px] shrink-0 font-bold text-[#0E1A2B]">
                · {row.label}
              </dt>
              <dd className="text-[#3E4756] leading-snug break-keep">
                {row.desc}
              </dd>
            </div>
          ))}
        </dl>

        {/* 터치형 현장 조건 선택 칩 */}
        <div className="mt-3">
          <div className="flex items-center justify-between gap-2 mb-1.5">
            <span className="text-hb-xs font-bold text-[#3E4756]">
              내 설치 조건 선택 (선택 시 문의 내용에 자동 첨부)
            </span>
            {selectedChips.length > 0 && (
              <button
                type="button"
                onClick={() => setSelectedChips([])}
                className="text-hb-xs font-semibold text-[#646E7E] underline"
              >
                선택 해제
              </button>
            )}
          </div>
          <div className="flex flex-wrap gap-1.5">
            {chips.map((chip) => {
              const active = selectedChips.includes(chip);
              return (
                <button
                  key={chip}
                  type="button"
                  onClick={() => toggleChip(chip)}
                  aria-pressed={active}
                  className={`rounded-md px-2.5 py-1 text-hb-xs font-semibold transition-colors border cursor-pointer ${
                    active
                      ? "bg-[#0E1A2B] text-white border-[#0E1A2B]"
                      : "bg-[#FAF9F7] text-[#3E4756] border-[#D8D3C8] hover:border-[#0E1A2B]"
                  }`}
                >
                  {active ? `✓ ${chip}` : `+ ${chip}`}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* 2. 다채널 즉시 상담 동선 (첫 화면에 바로 노출) */}
      <div className="pt-2 border-t border-[#E5E2DC] space-y-2">
        {sold && (
          <div className="rounded-lg border border-[#FADCD0] bg-[#FFF5F0] px-3 py-2 text-hb-xs text-[#B5431A] font-semibold leading-snug flex items-start gap-1.5">
            <Icon d={ICON.bell} className="w-4 h-4 shrink-0 mt-0.5 text-[#D9531E]" />
            <span>
              이 매물은 판매 완료되었으나 직영 매장에{" "}
              <strong className="underline">동일·유사 스펙 대기 매물</strong>이
              있을 수 있습니다.
            </span>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          <a
            href={telHref(STORE.tel)}
            className="hb-btn-accent h-11 px-3 sm:px-4 text-hb-xs sm:text-hb-sm"
          >
            <Icon d={ICON.phone} className="h-4 w-4 shrink-0" />
            <span className="whitespace-nowrap">
              {sold
                ? `유사 매물 전화 (${STORE.tel})`
                : `전화 문의 (${STORE.tel})`}
            </span>
          </a>

          <a
            href={STORE.kakaoChat}
            target="_blank"
            rel="noopener noreferrer"
            className="hb-btn-kakao h-11 px-3 sm:px-4 text-hb-xs sm:text-hb-sm"
          >
            <Icon d={ICON.chat} className="h-4 w-4 shrink-0" />
            <span className="whitespace-nowrap">{sold ? "카톡 유사 매물 찾기" : "카카오톡 상담"}</span>
          </a>
        </div>

        <div className="grid grid-cols-2 gap-2">
          <a
            href={smsHref(STORE.mobile, smsBody)}
            className="hb-btn-outline h-10 px-2 sm:px-3 text-hb-xs"
          >
            <Icon d={ICON.chat} className="h-3.5 w-3.5 text-[#D9531E] shrink-0" />
            <span className="truncate">
              {sold
                ? "유사 매물 문자"
                : selectedChips.length > 0
                ? `조건 포함 문자 (${selectedChips.length})`
                : `문자 문의 (${STORE.mobile})`}
            </span>
          </a>

          <Link
            href={inquiryHref}
            className="hb-btn-primary h-10 px-2 sm:px-3 text-hb-xs"
          >
            <Icon d={ICON.pen} className="h-3.5 w-3.5 text-[#FF8A50] shrink-0" />
            <span className="truncate">
              {sold
                ? "유사 매물 재고 문의"
                : selectedChips.length > 0
                ? `조건(${selectedChips.length}) 온라인 문의`
                : "온라인 견적 문의"}
            </span>
          </Link>
        </div>

        <QuoteBasketButton
          item={{
            id: String(product.id),
            title: product.title,
            category: categoryLabel,
            price: product.price,
            status: product.status,
            conditionGrade: product.condition_grade,
            description: envSummary
              ? `${product.description || ""}\n[현장조건: ${envSummary}]`
              : product.description,
            modelName,
            imageUrl: firstImageUrl,
            quantity: 1,
          }}
        />
      </div>
    </div>
  );
}


import React from "react";
import {
  getProductStatusLabel,
  isProductReserved,
  isProductSold,
  isRecentlyCreated,
} from "../../lib/site";

export function ProductStatusBadge({
  status,
  createdAt,
  showNew = true,
  className = "",
}: {
  status?: string | null;
  createdAt?: string | null;
  showNew?: boolean;
  className?: string;
}) {
  const sold = isProductSold(status);
  const reserved = isProductReserved(status);
  const label = getProductStatusLabel(status);

  const isFresh = showNew && !sold && isRecentlyCreated(createdAt, 7);

  return (
    <div className={`inline-flex flex-wrap items-center gap-1.5 ${className}`}>
      <span
        className={`inline-block rounded px-2.5 py-0.5 text-hb-xs font-bold tracking-wide text-white shadow-2xs ${
          sold
            ? "bg-[#646E7E]"
            : reserved
            ? "bg-[#B45309]"
            : "bg-[#0E1A2B]"
        }`}
      >
        {label}
      </span>
      {isFresh && (
        <span className="inline-block rounded bg-[#D9531E] px-2 py-0.5 text-hb-xs font-bold tracking-wide text-white shadow-2xs">
          NEW
        </span>
      )}
    </div>
  );
}


// 파일 경로: components/products/product-structured-description.tsx
"use client";

import React from "react";
import { parseProductDescription } from "../../lib/site";
import { Icon, ICON } from "../../lib/ui";

export interface ProductStructuredDescriptionProps {
  description: string | null | undefined;
  className?: string;
  variant?: "full" | "compact";
}

export function ProductStructuredDescription({
  description,
  className = "",
  variant = "full",
}: ProductStructuredDescriptionProps) {
  if (!description || !description.trim()) {
    return (
      <div className={`border-t-2 border-[#0E1A2B] pt-5 ${className}`.trim()}>
        <h3 className="text-hb-base font-bold text-[#0E1A2B] mb-2">
          상세 제원 및 검수 소견
        </h3>
        <p className="text-hb-sm leading-relaxed text-[#646E7E]">
          등록된 상세 설명이 없습니다. 매장 전화 또는 온라인 문의로 상세 스펙을 확인하실 수 있습니다.
        </p>
      </div>
    );
  }

  const parsed = parseProductDescription(description);

  if (!parsed.hasStructuredSections) {
    return (
      <div className={`border-t-2 border-[#0E1A2B] pt-5 ${className}`.trim()}>
        <h3 className="text-hb-base font-bold text-[#0E1A2B] mb-2.5">
          상세 제원 및 검수 소견
        </h3>
        <p className="text-hb-sm leading-relaxed text-[#3E4756] whitespace-pre-line">
          {description}
        </p>
      </div>
    );
  }

  const isCompact = variant === "compact";

  return (
    <div
      className={`border-t-2 border-[#0E1A2B] bg-white ${
        isCompact ? "pt-4 space-y-4" : "p-5 sm:p-7 rounded-b-xl border-x border-b border-[#E5E2DC] divide-y divide-[#E5E2DC]"
      } ${className}`.trim()}
    >
      {/* 상단 섹션 타이틀 (full 모드 전용) */}
      {!isCompact && (
        <div className="pb-4 flex flex-wrap items-baseline justify-between gap-2">
          <div>
            <span className="hb-eyebrow">SHOWROOM SPECIFICATION</span>
            <h2 className="mt-1 text-hb-lg sm:text-hb-xl font-bold text-[#0E1A2B]">
              상세 규격 · 제품 특징 · 검수 소견서
            </h2>
          </div>
          <span className="text-hb-xs font-semibold text-[#646E7E]">
            직영 매장 입고 실물 기준
          </span>
        </div>
      )}

      {/* 1. 한눈에 보는 제품 정보 (요약) */}
      {parsed.summary.length > 0 && (
        <div className={isCompact ? "" : "py-4"}>
          <h3 className="text-hb-sm font-bold text-[#0E1A2B] mb-2 flex items-center gap-1.5">
            <Icon d={ICON.check} className="h-4 w-4 text-[#D9531E]" />
            <span>한눈에 보는 제품 요약</span>
          </h3>
          <div className="space-y-1 text-hb-sm leading-relaxed text-[#2D333F]">
            {parsed.summary.map((line, i) => (
              <p key={i} className="leading-relaxed text-[#3E4756]">
                {line}
              </p>
            ))}
          </div>
        </div>
      )}

      {/* 2. 주요 규격 및 사양 (2열 아키텍처 스펙 테이블) */}
      {parsed.specs.length > 0 && (
        <div className={isCompact ? "" : "py-4"}>
          <h3 className="text-hb-sm font-bold text-[#0E1A2B] mb-2.5">
            주요 규격 및 사양
          </h3>
          <dl
            className={`grid grid-cols-1 ${
              !isCompact && parsed.specs.length > 2 ? "sm:grid-cols-2 sm:gap-x-8" : ""
            } border-t border-[#E5E2DC] text-hb-sm`}
          >
            {parsed.specs.map((s, i) => (
              <div
                key={s.label + i}
                className="py-2.5 border-b border-[#E5E2DC] flex justify-between items-baseline gap-4"
              >
                <dt className="font-semibold text-[#646E7E] shrink-0">
                  {s.label}
                </dt>
                <dd className="font-bold text-[#0E1A2B] text-right break-keep">
                  {s.value}
                </dd>
              </div>
            ))}
          </dl>
        </div>
      )}

      {/* 3 & 4. 제품 특징 + 점검 및 A/S 안내 (2열 병렬 또는 순차 배치) */}
      {(parsed.features.length > 0 || parsed.inspectionAndAs.length > 0) && (
        <div
          className={`${
            isCompact
              ? "space-y-4"
              : "py-4 grid grid-cols-1 md:grid-cols-2 gap-6"
          }`}
        >
          {parsed.features.length > 0 && (
            <div>
              <h3 className="text-hb-sm font-bold text-[#0E1A2B] mb-2">
                제품 핵심 특징
              </h3>
              <ul className="space-y-1.5 text-hb-sm leading-relaxed text-[#3E4756]">
                {parsed.features.map((f, i) => (
                  <li key={i} className="flex items-start gap-2">
                    <span className="text-[#D9531E] font-extrabold">·</span>
                    <span>{f}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {parsed.inspectionAndAs.length > 0 && (
            <div>
              <h3 className="text-hb-sm font-bold text-[#0E1A2B] mb-2">
                점검 및 보증 안내
              </h3>
              <ul className="space-y-1.5 text-hb-sm leading-relaxed text-[#3E4756]">
                {parsed.inspectionAndAs.map((as, i) => (
                  <li key={i} className="flex items-start gap-2">
                    <Icon
                      d={ICON.check}
                      className="h-4 w-4 text-[#15803D] shrink-0 mt-0.5"
                    />
                    <span>{as}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {/* 5 & 6. 구매 및 설치 전 확인사항 + 상담 안내 */}
      {(parsed.checkPoints.length > 0 || parsed.consultationGuide.length > 0) && (
        <div className={isCompact ? "space-y-3" : "pt-4 space-y-3"}>
          {parsed.checkPoints.length > 0 && (
            <div className="border-l-2 border-[#D9531E] bg-[#FAF9F7] pl-3.5 pr-3 py-2.5 text-hb-sm text-[#3E4756]">
              <strong className="block font-bold text-[#0E1A2B] mb-1">
                구매 및 설치 전 확인사항
              </strong>
              {parsed.checkPoints.map((c, i) => (
                <p key={i}>· {c}</p>
              ))}
            </div>
          )}

          {parsed.consultationGuide.length > 0 && (
            <div className="text-hb-sm text-[#434B59] leading-relaxed space-y-1">
              {parsed.consultationGuide.map((cg, i) => (
                <p key={i} className="flex items-start gap-1.5">
                  <Icon
                    d={ICON.chat}
                    className="w-4 h-4 text-[#D9531E] shrink-0 mt-0.5"
                  />
                  <span>{cg}</span>
                </p>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 7. 기타 원문 내용 */}
      {parsed.rawRest.length > 0 && (
        <div className={`${isCompact ? "" : "pt-4"} text-hb-sm leading-relaxed text-[#0E1A2B] whitespace-pre-line`}>
          {parsed.rawRest.join("\n")}
        </div>
      )}
    </div>
  );
}


// 파일 경로: components/products/v2-spatial-fit-planner.tsx
"use client";

import React, { useState, useMemo } from "react";
import Link from "next/link";
import {
  normalizeProductCategory,
  smsHref,
  STORE,
  trackEvent,
} from "../../lib/site";
import { Icon, ICON } from "../../lib/ui";

export function extractDimensionsFromText(
  title?: string | null,
  description?: string | null,
  categoryRaw?: string | null
): {
  widthMm: number;
  depthMm: number;
  heightMm: number | null;
  isExact: boolean;
} {
  const text = `${title || ""}\n${description || ""}`;
  const cat = normalizeProductCategory(categoryRaw);

  const tripleMatch = text.match(
    /\b(\d{3,4})\s*[x×*]\s*(\d{3,4})\s*[x×*]\s*(\d{3,4})\b/i
  );
  if (tripleMatch) {
    const w = Number(tripleMatch[1]);
    const d = Number(tripleMatch[2]);
    const h = Number(tripleMatch[3]);
    if (w >= 350 && w <= 3000) {
      return { widthMm: w, depthMm: d, heightMm: h, isExact: true };
    }
  }

  const widthMmMatch = text.match(/(?:가로|폭)\s*[:：]?\s*(\d{3,4})\s*mm/i);
  if (widthMmMatch) {
    return {
      widthMm: Number(widthMmMatch[1]),
      depthMm: 750,
      heightMm: null,
      isExact: true,
    };
  }
  const widthCmMatch = text.match(/(?:가로|폭)\s*[:：]?\s*(\d{2,3})\s*cm/i);
  if (widthCmMatch) {
    return {
      widthMm: Number(widthCmMatch[1]) * 10,
      depthMm: 750,
      heightMm: null,
      isExact: true,
    };
  }

  if (/45\s*박스/.test(text)) {
    return { widthMm: 1260, depthMm: 800, heightMm: 1900, isExact: false };
  }
  if (/25\s*박스|30\s*박스/.test(text)) {
    return { widthMm: 650, depthMm: 800, heightMm: 1900, isExact: false };
  }
  if (/1800/.test(text)) {
    return { widthMm: 1800, depthMm: 750, heightMm: 850, isExact: false };
  }
  if (/1500/.test(text)) {
    return { widthMm: 1500, depthMm: 750, heightMm: 850, isExact: false };
  }
  if (/1200/.test(text)) {
    return { widthMm: 1200, depthMm: 750, heightMm: 850, isExact: false };
  }
  if (/양문형|4\s*도어|비스포크|오브제/.test(text)) {
    return { widthMm: 910, depthMm: 850, heightMm: 1830, isExact: false };
  }
  if (cat === "세탁기/건조기") {
    return { widthMm: 690, depthMm: 750, heightMm: 990, isExact: false };
  }
  if (cat === "냉장고") {
    return { widthMm: 600, depthMm: 670, heightMm: 1650, isExact: false };
  }

  return { widthMm: 850, depthMm: 750, heightMm: null, isExact: false };
}

const SPACE_PRESETS = [
  { label: "원룸·좁은틈 (90cm)", cm: 90 },
  { label: "소형 주방 (120cm)", cm: 120 },
  { label: "일반 가정집 (150cm)", cm: 150 },
  { label: "넓은 벽면 (220cm)", cm: 220 },
] as const;

const DOOR_PRESETS = [
  { label: "좁은 방문 (75cm)", cm: 75 },
  { label: "일반 방문 (80cm)", cm: 80 },
  { label: "아파트 현관 (90cm)", cm: 90 },
  { label: "상가·양개문 (110cm+)", cm: 115 },
] as const;

export function V2SpatialFitPlanner({
  productId,
  title,
  description,
  category,
  overrideWidthMm,
  className = "",
}: {
  productId?: string;
  title?: string | null;
  description?: string | null;
  category?: string | null;
  overrideWidthMm?: number | null;
  className?: string;
}) {
  const catLabel = normalizeProductCategory(category);
  const combinedText = `${title || ""}\n${description || ""}`;

  // 현재 보고 있는 상품 자체가 삼상(380V) 전용인지 단상(220V)인지 자동 감지
  const isProductThreePhase = /삼상|380\s*V/i.test(combinedText);
  const isProductSinglePhase = /단상|220\s*V/i.test(combinedText);

  /* 에어컨/냉난방기 선택 상태 */
  const [outdoorSpot, setOutdoorSpot] = useState<
    "ground" | "angle" | "rooftop"
  >("ground");
  const [pipeDistance, setPipeDistance] = useState<"short" | "long">("short");
  const [powerType, setPowerType] = useState<"220v" | "380v" | "unknown">(
    isProductThreePhase ? "380v" : "220v"
  );

  /* 냉장고/세탁기/업소용 공간 & 운반 층수 선택 상태 */
  const detected = useMemo(
    () => extractDimensionsFromText(title, description, catLabel),
    [title, description, catLabel]
  );

  const productWidthCm = Math.round(
    (overrideWidthMm || detected.widthMm) / 10
  );
  const productDepthCm = Math.round(detected.depthMm / 10);
  const clearanceCm = 10;
  const requiredSpaceCm = productWidthCm + clearanceCm;

  const [mySpaceCm, setMySpaceCm] = useState<number>(
    Math.max(120, requiredSpaceCm + 30)
  );
  const [myDoorCm, setMyDoorCm] = useState<number>(90);
  const [carryFloor, setCarryFloor] = useState<"1f_elev" | "stairs">("1f_elev");

  /* ──────────────────────────────────────────────────────────
     분기 A: 에어컨·냉난방기 — 호환성 판정 & 설치비 발생 항목 계산기
     ────────────────────────────────────────────────────────── */
  if (catLabel === "에어컨/냉난방기") {
    const hasPowerMismatch =
      (isProductThreePhase && powerType === "220v") ||
      (isProductSinglePhase && powerType === "380v");

    const spotLabel =
      outdoorSpot === "ground"
        ? "1층·베란다 바닥"
        : outdoorSpot === "angle"
        ? "외벽 앵글 거치"
        : "옥상·원거리";
    const pipeLabel =
      pipeDistance === "short" ? "기본거리(5~8m)" : "먼거리(연장필요)";
    const powerLabel =
      powerType === "220v"
        ? "단상 220V"
        : powerType === "380v"
        ? "삼상 380V"
        : "전원 미확인";

    const envSummary = `실외기:${spotLabel} / 배관:${pipeLabel} / 전원:${powerLabel}`;

    // 기본 포함 vs 별도 확인 항목을 구매자 관점에서 명확히 분류
    const basicItems: string[] = [
      "실내기 + 전용 실외기 + 리모컨 본체 세트",
      "출고 전 냉매 정량 충진 및 고압 살균 세척",
    ];
    const extraCheckItems: string[] = [];

    if (outdoorSpot === "ground") {
      basicItems.push("바닥 거치 환경 (별도 외벽 앵글 자재비 없음)");
    } else if (outdoorSpot === "angle") {
      extraCheckItems.push(
        "외벽 앵글: 기존 앵글 재사용 시 무료 / 신규 앵글 설치 시 자재비·위험수당 별도"
      );
    } else {
      extraCheckItems.push(
        "옥상·특수 거치: 옥상 배관 인양 및 고정 작업 여건 사전 확인 필요"
      );
    }

    if (pipeDistance === "short") {
      extraCheckItems.push(
        "기본 배관(5~8m 이내) 시공 및 벽체 타공(구멍 없는 경우 1홀 기준) 여부 확인"
      );
    } else {
      extraCheckItems.push(
        "배관 연장: 기본 길이 초과분은 1m당 추가 배관비 및 냉매 보충비 발생"
      );
    }

    if (powerType === "380v") {
      extraCheckItems.push(
        "삼상 380V 전원: 매장 분전반(4선식 차단기) 위치 및 전원선 연결 거리 확인"
      );
    }

    const smsBody = `[한밭중고전자 에어컨 설치견적 문의]\n• 상품: ${
      title || "에어컨/냉난방기"
    }\n• 내 설치조건: ${envSummary}\n위 조건으로 기기값 포함 예상 설치 견적 문의드립니다.`;

    const inquiryUrlParams = new URLSearchParams({
      write: "1",
      type: "구매 문의",
      ...(productId ? { productId } : {}),
      title: `[설치견적 문의] ${title || "에어컨/냉난방기"}`,
      category: catLabel,
      envNote: envSummary,
    });

    return (
      <div className={`flex h-full flex-col justify-between rounded-2xl border border-[#E5E2DC] bg-white p-5 sm:p-6 shadow-2xs space-y-5 ${className}`}>
        <div className="space-y-4">
          {/* 상단 헤더 */}
          <div className="border-b border-[#E5E2DC] pb-4">
            <span className="inline-flex items-center gap-1.5 rounded-md bg-[#FFF5F0] border border-[#FADCD0] px-2.5 py-1 text-hb-xs font-bold text-[#D9531E]">
              <Icon d={ICON.snowflake} className="w-3.5 h-3.5 text-[#D9531E] shrink-0" />
              <span>에어컨 설치비 · 호환성 판별기</span>
            </span>
            <h3 className="mt-2.5 text-hb-lg sm:text-hb-xl font-extrabold text-[#0E1A2B] tracking-tight">
